      for (const x of valid) {
        if (!win) { win = x; continue; }
        const [d, why] = this.compare(x, win);
        if (d < 0) { win = x; reason = why; } else if (!reason) reason = why;
      }
      for (const x of list) x.best = x === win;
      if (win) win.reason = valid.length > 1 ? reason : 'only path';
      best.set(prefix, { list, win });
    }
    const before = JSON.stringify([...this.best].map(([k, v]) => [k, v.win?.from, v.win?.attrs?.nextHop]));
    this.best = best;
    const after = JSON.stringify([...best].map(([k, v]) => [k, v.win?.from, v.win?.attrs?.nextHop]));
    if (before !== after && !force) {
      const n = [...best.values()].filter(v => v.win && !v.win.local).length;
      this.rec('info', `BGP best paths recomputed: ${n} route${n === 1 ? '' : 's'} learned from neighbors in use`, { tag: 'bgp-best', data: { routes: n } });
    }
    this.dev.evpn?.recomputeBgp?.();
    for (const p of this.peers.values()) if (p.state === 'Established') this.advertise(p);
  }
  /** What a neighbor gets: the rules for eBGP and iBGP, split horizon and route reflection */
  outFor(p) {
    const out = new Map();
    const ebgp = this.ebgp(p.cfg), rr = this.isRR();
    const local = p.sock?.local || this.localIp(p.cfg);
    for (const [prefix, { win }] of this.best) {
      if (!win) continue;
      if (win.from === p.ip) continue;
      if (win.ibgp && !ebgp) {
        // iBGP split horizon: never pass an iBGP route to another iBGP neighbor, unless reflecting it
        const fromClient = !!this.nbrs().find(n => n.ip === win.from)?.rrClient;
        if (!rr || (!fromClient && !p.cfg.rrClient)) continue;
      }
      const a = win.attrs;
      let attrs;
      if (ebgp) {
        const prep = Math.max(0, Number(p.cfg.prepend) || 0);
        attrs = { origin: a.origin, asPath: [...Array(prep + 1).fill(this.asn), ...a.asPath], nextHop: local, ...(p.cfg.med !== '' && p.cfg.med != null ? { med: Number(p.cfg.med) } : {}) };
      } else {
        const self = win.local || p.cfg.nextHopSelf && win.ebgp;
        attrs = { origin: a.origin, asPath: [...a.asPath], nextHop: self ? local : a.nextHop, localPref: a.localPref ?? 100, ...(a.med != null ? { med: a.med } : {}) };
        if (win.ibgp && rr) { attrs.originatorId = a.originatorId || win.rid; attrs.clusterList = [this.rid, ...(a.clusterList || [])]; }
      }
      out.set(prefix, attrs);
    }
    return out;
  }
  advertise(p) {
    const want = this.outFor(p);
    const withdrawn = [...p.out.keys()].filter(k => !want.has(k));
    const groups = new Map();
    for (const [prefix, attrs] of want) {
      const key = JSON.stringify(attrs);
      if (p.out.get(prefix) === key) continue;
      if (!groups.has(key)) groups.set(key, []);
      groups.get(key).push(prefix);
    }
    for (const w of withdrawn) p.out.delete(w);
    if (withdrawn.length) { this.send(p, { type: 'UPDATE', withdrawn, nlri: [], attrs: {} }); this.rec('info', `withdraws ${withdrawn.join(', ')} at ${p.ip}`, { tag: 'bgp-withdraw-sent', data: { peer: p.ip } }); }
    for (const [key, list] of groups) {
      const attrs = JSON.parse(key);
      for (const x of list) p.out.set(x, key);
      this.send(p, { type: 'UPDATE', withdrawn: [], nlri: list, attrs });
      this.rec('info', `announces ${list.join(', ')} to ${p.ip}: AS path ${asPathText(attrs.asPath) || '(empty)'}, next hop ${attrs.nextHop}`, { tag: 'bgp-update-sent', data: { peer: p.ip, prefixes: list } });
    }
    this.advertiseEvpn(p);
  }
  /** EVPN routes, only when both sides announced the address family in their OPEN */
  evpnOk(p) { return !!p.cfg.evpn && (p.remoteCaps || []).includes('L2VPN EVPN'); }
  evpnOut(p) {
    const out = new Map();
    if (!this.evpnOk(p)) return out;
    const local = p.sock?.local || this.localIp(p.cfg);
    for (const r of this.dev.evpn?.localRoutes() || []) out.set(r.key, { ...r, nextHop: local });
    const rr = this.isRR();
    for (const q of this.peers.values()) {
      if (q === p || q.state !== 'Established' || !this.evpnOk(q)) continue;
      // The same reflection rules as for IPv4 routes
      if (!rr || (!q.cfg.rrClient && !p.cfg.rrClient)) continue;
      for (const [k, e] of q.rxEvpn) {
        if (out.has(k) || (e.originatorId || q.remoteRid) === p.remoteRid) continue;
        out.set(k, { ...e, originatorId: e.originatorId || q.remoteRid });
      }
    }
    return out;
  }
  advertiseEvpn(p) {
    const want = this.evpnOut(p);
    const withdrawn = [...p.outEvpn.keys()].filter(k => !want.has(k));
    const add = [];
    for (const [k, e] of want) { const j = JSON.stringify(e); if (p.outEvpn.get(k) !== j) { add.push(e); p.outEvpn.set(k, j); } }
    for (const k of withdrawn) p.outEvpn.delete(k);
    if (!add.length && !withdrawn.length) return;
    this.send(p, { type: 'UPDATE', withdrawn: [], nlri: [], evpn: add, evpnWithdrawn: withdrawn, attrs: { origin: 'i', asPath: [], nextHop: add[0]?.nextHop || p.sock?.local, localPref: 100 } });
    if (add.length) this.rec('info', `announces ${add.length} EVPN route${add.length === 1 ? '' : 's'} to ${p.ip}: ${add.map(e => e.rt === 2 ? `type 2 ${e.mac}` : `type 3 VNI ${e.vni}`).join(', ')}`, { tag: 'bgp-evpn-sent', data: { peer: p.ip, count: add.length } });
  }
  /** Routes for the routing table: the best path of every prefix learned from a neighbor */
  routes() {
    if (!this.enabled) return [];
    const out = [];
    for (const [prefix, { win }] of this.best) {
      if (!win || win.local || !win.valid) continue;
      const nh = this.resolve(win.attrs.nextHop);
      if (!nh) continue;
      const c = parseCidr(prefix);
      out.push({ net: c.net, len: c.len, via: nh.via, dev: nh.dev, proto: 'B', ibgp: win.ibgp, metric: win.attrs.med ?? 0, bgpNh: win.attrs.nextHop, asPath: win.attrs.asPath });
    }
    return out;
  }
  summary() {
    return [...this.peers.values()].map(p => ({ ip: p.ip, as: Number(p.cfg.remoteAs), state: p.state, up: p.upSince === null ? null : Math.round((this.sim.time - p.upSince) / 1000),
      pfx: p.rx.size, evpn: p.rxEvpn.size, msgsIn: p.msgsIn, msgsOut: p.msgsOut, type: this.ebgp(p.cfg) ? 'eBGP' : 'iBGP', error: p.lastError }));
  }
  table() {
    const rows = [];
    for (const [prefix, { list }] of [...this.best].sort((a, b) => ipCmp(a[0].split('/')[0], b[0].split('/')[0]))) {
      for (const x of list.sort((a, b) => (b.best - a.best))) rows.push({ prefix, best: x.best, valid: x.valid, ibgp: !!x.ibgp, nextHop: x.attrs.nextHop, med: x.attrs.med ?? 0, localPref: x.local || x.ibgp ? x.attrs.localPref ?? 100 : null, weight: x.weight, asPath: x.attrs.asPath, origin: x.attrs.origin, from: x.from, why: x.why, reason: x.reason });
    }
    return rows;
  }
}
__PACKETPILOT_FILE_END__
  mkdir -p "$W/js"
  cat > "$W/js/challenges.js" <<'__PACKETPILOT_FILE_END__'
// Troubleshooting challenges: a network with a hidden fault, a symptom and a goal.
// Every challenge has several variants with a different cause, one is picked at random.
import { PRESETS, chainTopo, vlanTopo, tcpPathTopo, dhcpTopo, natTopo, ospfTopo, vrrpTopo, stpTriangle, stpSquare, servicesTopo, bfdTopo, ecmpTopo, dnsTopo, ipv6Topo, vpnTopo, bgpPairTopo, ibgpTopo, bgpMultiTopo, evpnTopo } from './presets.js';
import { macFor } from './net.js';
import { wgPubKey, wgGenKey } from './vpn.js';

const preset = id => PRESETS.find(p => p.id === id).make();
const dev = (t, id) => t.devices.find(d => d.id === id);
const link = (t, a, b) => t.links.find(l => (l.a.dev === a && l.b.dev === b) || (l.a.dev === b && l.b.dev === a));

// Goal checks
const pingAfterStart = (from, to) => sim => sim.log.some(e => e.tag === 'ping-done' && e.dev === from && e.data.dst === to && e.data.received > 0);
const curlOk = (from, port = 80) => sim => sim.log.some(e => e.dev === from && e.tag === 'tcp-done' && e.data.ok && e.data.mode === 'http' && (!port || e.data.port === port));
const leased = d => sim => !!sim.dev(d)?.l3?.lease;
const dnsOk = (from, name) => sim => sim.log.some(e => e.dev === from && e.tag === 'dns-done' && e.data.ok && e.data.answer && e.data.name === name);

// In the ring, sw3 reaches the root via sw2 or sw4 at equal cost: the lower bridge MAC wins
const ringBackup = () => [['sw2', macFor('sw2/bridge')], ['sw4', macFor('sw4/bridge')]].sort((a, b) => b[1].localeCompare(a[1]))[0][0];
// sw3 lost its root port while pc1 pinged pc3, and the ping lost at most one reply
const fastFailover = sim => sim.log.some(cut => {
  if (cut.tag !== 'link-down' || !/ sw3 /.test(cut.text) || /pc3/.test(cut.text)) return false;
  const moved = sim.log.some(e => e.seq > cut.seq && e.dev === 'sw3' && e.tag === 'stp-role' && e.data?.role === 'root');
  const d = sim.log.find(e => e.tag === 'ping-done' && e.dev === 'pc1' && e.data.dst === '10.0.0.3' && e.seq > cut.seq && e.t - e.data.sent * 1000 - 1500 < cut.t);
  return moved && !!d && d.data.sent - d.data.received <= 1;
});

// pc1 kept pinging while BFD on r1 declared a neighbor dead, and lost at most two replies.
// BFD hellos fill the capped log fast, so the moments are remembered per simulation.
const bfdDowns = new WeakMap();
const bfdFailover = sim => {
  const seen = bfdDowns.get(sim) || new Set(); bfdDowns.set(sim, seen);
  for (const e of sim.log) if (e.tag === 'bfd-state' && e.dev === 'r1' && e.data?.state === 'Down') seen.add(e.t);
  return sim.log.some(d => d.tag === 'ping-done' && d.dev === 'pc1' && d.data.sent >= 5 && d.data.sent - d.data.received <= 2
    && [...seen].some(t => t < d.t && t > d.t - d.data.sent * 1000 - 1500));
};
// r1 has (at least) two next hops for the server network
const ecmpPaths = sim => (sim.dev('r1')?.l3?.lookupAll('10.4.0.10') || []).length >= 2 && Number(sim.dev('r1').cfg.maxPaths ?? 4) >= 2;

export const LEVELS = { 1: 'Easy', 2: 'Medium', 3: 'Hard' };

export const CHALLENGES = [
  { id: 'gateway', level: 1, title: 'The new PC only reaches its own network', topics: ['Gateway', 'Subnet mask'],
    symptom: '<p>A colleague set up <b>pc1</b>. It can ping pc2 next to it, but not the server srv1 behind the router. pc2 works fine.</p>',
    topo: () => preset('routed'),
    variants: [
      { fault: t => { dev(t, 'pc1').gw = '192.168.10.254'; }, cause: 'pc1 had the wrong default gateway 192.168.10.254. Nobody answers ARP for it, so pc1 reports "Destination Host Unreachable" for everything outside its network.' },
      { fault: t => { dev(t, 'pc1').gw = ''; }, cause: 'pc1 had no default gateway at all. Without one, Linux answers "Network is unreachable" for every address outside its own subnet.' },
      { fault: t => { dev(t, 'pc1').ifaces.eth1.prefix = 16; }, cause: 'pc1 had the prefix /16 instead of /24. It believed 192.168.20.20 was in its own network and asked for it via ARP directly instead of going through the gateway.' }],
    goals: [{ text: 'pc1 reaches srv1 (192.168.20.20).', check: pingAfterStart('pc1', '192.168.20.20') }],
    hints: ['Compare the configuration of pc1 and pc2.', 'Watch what pc1 asks for via ARP when you ping srv1.'],
    presets: { pc1: ['ping -c 2 192.168.20.20', 'ip route', 'ip addr', 'ip neigh'], pc2: ['ip route', 'ip addr'] } },

  { id: 'oneway', level: 2, title: 'The ping gets there, but never comes back', topics: ['Routing', 'Return path'],
    symptom: '<p>pc1 cannot reach srv1 across three routers. The admin of srv1 swears the pings arrive.</p>',
    topo: () => chainTopo(),
    variants: [
      { fault: t => { dev(t, 'r2').routes = [{ dst: '10.0.4.0/24', via: '10.0.23.3' }]; }, cause: 'r2 had no route back to 10.0.1.0/24. The echo request went through, the reply died at r2 with "no route".' },
      { fault: t => { dev(t, 'r3').routes = []; }, cause: 'r3 had lost its default route. It could deliver to srv1 but not send the reply back towards pc1.' },
      { fault: t => { dev(t, 'srv1').gw = '10.0.4.254'; }, cause: 'srv1 had the wrong gateway 10.0.4.254. Its replies never left its own network.' }],
    goals: [{ text: 'pc1 reaches srv1 (10.0.4.10).', check: pingAfterStart('pc1', '10.0.4.10') }],
    hints: ['Filter the log to srv1: does the echo request arrive?', 'Follow the reply: which device drops it, and why?'],
    presets: { pc1: ['ping -c 1 10.0.4.10', 'traceroute 10.0.4.10'], srv1: ['ip route'], r2: ['ip route'], r3: ['ip route'] } },

  { id: 'storm', level: 1, title: 'Everything stopped after the new cable', topics: ['STP', 'Loop'],
    symptom: '<p>Someone added a third cable between the switches "for redundancy". Since then, the first ping brings the whole network down.</p>',
    topo: () => stpTriangle({ enabled: true, rootPrio: 4096 }),
    variants: [
      { fault: t => { for (const id of ['sw1', 'sw2', 'sw3']) dev(t, id).stp.enabled = false; }, cause: 'Spanning tree was off on all three switches. With the triangle of cables there was a loop, and the first broadcast circled forever.' },
      { fault: t => { dev(t, 'sw3').stp.enabled = false; dev(t, 'sw2').stp.enabled = false; }, cause: 'Spanning tree was off on sw2 and sw3. sw1 alone could not block the loop, because the port that has to block was on a switch without STP.' }],
    goals: [{ text: 'pc1 pings pc2 (10.0.0.2) without a broadcast storm.', check: sim => !sim.halted && pingAfterStart('pc1', '10.0.0.2')(sim) }],
    hints: ['After a storm, reset the state with the circular arrow button.', 'Which protocol prevents loops on layer 2, and is it running on every switch?'],
    presets: { pc1: ['ping -c 2 10.0.0.2'], sw1: ['show spanning-tree'], sw2: ['show spanning-tree'], sw3: ['show spanning-tree'] } },

  { id: 'rstp', level: 2, title: 'Rapid spanning tree, but not rapid', topics: ['RSTP', 'Failover'],
    symptom: '<p>The ring was switched to rapid spanning tree last month. Still, when a cable to <b>sw3</b> fails, phone calls drop for half a minute. RSTP should fail over without losing a single packet.</p>',
    topo: () => stpSquare({ mode: 'rstp', timers: 'standard', edge: true }),
    variants: [
      { fault: t => { dev(t, 'sw3').stp.mode = 'stp'; }, cause: 'sw3 itself still ran classic STP (802.1D). Its alternate port could only become the root port after listening and learning, 30 seconds. Its RSTP neighbors had fallen back to STP on their ports towards it, too.' },
      { fault: t => { dev(t, ringBackup()).stp.mode = 'stp'; }, cause: 'The switch on the backup path of sw3 still ran classic STP. sw3 spoke STP on that port ("Peer(STP)"), so its alternate port had to go through the timers before it could forward.' }],
    goals: [{ text: 'Cut the cable on the root port of sw3 while pc1 pings pc3 (10.0.0.3). The ping loses at most one reply.', check: fastFailover }],
    hints: ['Find the root port of sw3 with show spanning-tree, then cut that cable during a long ping.', 'Look for "Peer(STP)" in show spanning-tree and for "falls back to STP" in the log.'],
    presets: { pc1: ['ping -c 40 10.0.0.3'], sw3: ['show spanning-tree', 'ip link set eth1 down', 'ip link set eth2 down'], sw2: ['show spanning-tree'], sw4: ['show spanning-tree'] } },

  { id: 'ecmp', level: 2, title: 'The second path sits idle', topics: ['ECMP', 'OSPF'],
    symptom: '<p>The company paid for a second path to the server network via r3, so r1 can spread the load over r2 and r3. The monitoring shows that r3 carries no traffic at all, every flow goes via r2.</p>',
    topo: () => ecmpTopo(),
    variants: [
      { fault: t => { dev(t, 'r1').maxPaths = 1; }, cause: 'r1 was limited to one path (maximum-paths 1). OSPF found two equal routes, but r1 only installed one of them.' },
      { fault: t => { dev(t, 'r1').ospf.ifaces.eth2.cost = 20; }, cause: 'The OSPF cost of eth2 on r1 was 20 instead of 10. The path via r3 cost 40 instead of 30, so it was no longer equal, and ECMP only uses equal paths.' },
      { fault: t => { dev(t, 'r3').ospf.ifaces.eth2.cost = 15; }, cause: 'r3 had cost 15 on its link to r4. The difference was two hops away from r1, but it still made the path via r3 more expensive (35 against 30).' }],
    goals: [{ text: 'r1 has two next hops for 10.4.0.0/24 in its routing table.', check: ecmpPaths },
      { text: 'c1 and c2 still reach the server (10.4.0.10).', check: sim => pingAfterStart('c1', '10.4.0.10')(sim) && pingAfterStart('c2', '10.4.0.10')(sim) }],
    hints: ['show ip route on r1: how many next hops does 10.4.0.0/24 have? show ip ospf interface shows the costs.', 'Add up the costs of both paths. ECMP needs exactly the same total, and r1 must be allowed to use more than one path (Load balancing).'],
    presets: { r1: ['show ip route', 'show ip ospf interface'], r3: ['show ip ospf interface'], c1: ['ping -c 1 10.4.0.10'], c2: ['ping -c 1 10.4.0.10'] } },

  { id: 'bfd', level: 3, title: 'BFD is set up, but nothing is faster', topics: ['BFD', 'OSPF', 'Failover'],
    symptom: '<p>Last month the team set up BFD between r1 and r2 so a dying provider link is noticed in under a second. Yesterday the provider silently dropped all traffic again, and pc1 still lost the server for 40 seconds.</p>',
    topo: () => bfdTopo({ bfd: ['r1', 'r2'] }),
    variants: [
      { fault: t => { dev(t, 'r2').bfd.enabled = false; }, cause: 'BFD was only turned on on r1. A BFD session needs both neighbors: r1 kept sending, nobody answered, the session never left Down, so nothing watched the provider link.' },
      { fault: t => { dev(t, 'r1').bfd.ospf = false; dev(t, 'r2').bfd.ospf = false; }, cause: 'BFD was enabled on both routers, but nobody used it: "Watch the OSPF neighbors" was off, so no session was ever created. BFD only helps its clients.' },
      { fault: t => { dev(t, 'r2').bfd = { enabled: false, interval: 300, mult: 3, ospf: false }; dev(t, 'r3').bfd = { enabled: true, interval: 300, mult: 3, ospf: true }; }, cause: 'BFD was configured on r1 and r3 instead of r1 and r2. The session that mattered, across the provider switch, never existed.' }],
    goals: [{ text: 'While pc1 pings the server (10.2.0.10), set the loss of the cable prov–r2 to 100 %. The ping loses at most two replies.', check: bfdFailover }],
    hints: ['show bfd peers on r1 and r2: which sessions exist, and in which state?', 'BFD is under Configuration, Add a feature, BFD. It needs both neighbors and "Watch the OSPF neighbors".'],
    presets: { pc1: ['ping -c 60 10.2.0.10'], r1: ['show bfd peers', 'show ip ospf neighbor'], r2: ['show bfd peers'], r3: ['show bfd peers'] } },

  { id: 'vlan', level: 2, title: 'VLAN 20 is cut in half', topics: ['VLAN', 'Trunk'],
    symptom: '<p>a10 and b10 in VLAN 10 work. a20 and b20 in VLAN 20 cannot reach each other, even though they are in the same VLAN.</p>',
    topo: () => vlanTopo(true),
    variants: [
      { fault: t => { dev(t, 's2').ports.eth8.allowed = '10'; }, cause: 'The trunk on s2 only allowed VLAN 10. Frames tagged with VLAN 20 were dropped at s2.' },
      { fault: t => { dev(t, 's1').ports.eth2 = { mode: 'access', vlan: 10 }; }, cause: 'The port of a20 on s1 was an access port in VLAN 10 instead of 20. a20 was in the wrong VLAN.' },
      { fault: t => { dev(t, 's1').ports.eth8.allowed = '10,30'; }, cause: 'The trunk on s1 allowed VLANs 10 and 30, but not 20. A typo in the allowed list.' }],
    goals: [{ text: 'a20 reaches b20 (10.20.0.2).', check: pingAfterStart('a20', '10.20.0.2') }, { text: 'a10 still reaches b10 (10.10.0.2).', check: pingAfterStart('a10', '10.10.0.2') }],
    hints: ['The log of each switch tells you when it drops a frame and why.', 'Compare the port configuration of s1 and s2.'],
    presets: { a20: ['ping -c 1 10.20.0.2'], a10: ['ping -c 1 10.10.0.2'], s1: ['bridge fdb'], s2: ['bridge fdb'] } },

  { id: 'dhcp', level: 1, title: 'New clients get no address', topics: ['DHCP', 'Relay'],
    symptom: '<p>The clients in 10.10.0.0/24 boot, but never get an address. The DHCP server in 10.20.0.0/24 is running.</p>',
    topo: () => dhcpTopo({ relay: true }),
    variants: [
      { fault: t => { delete dev(t, 'r1').ifaces.eth1.helper; }, cause: 'r1 had no DHCP relay (helper address) on eth1. The broadcasts of the clients stopped at the router.' },
      { fault: t => { dev(t, 'r1').ifaces.eth1.helper = '10.20.0.68'; }, cause: 'The helper address on r1 pointed to 10.20.0.68 instead of the server 10.20.0.67. The relayed requests went nowhere.' },
      { fault: t => { dev(t, 'dhcp').dhcpServer.pools[0].net = '10.11.0.0/24'; }, cause: 'The pool on the server was for 10.11.0.0/24. The relay marked the requests with giaddr 10.10.0.1, and the server had no pool for that network.' }],
    goals: [{ text: 'client1 gets an address.', check: leased('client1') }, { text: 'client2 gets an address.', check: leased('client2') }],
    hints: ['Let a client ask again with dhclient and follow the Discover.', 'Look at the logs of r1 and of the server.'],
    presets: { client1: ['dhclient', 'ip addr'], client2: ['dhclient'], dhcp: ['show ip dhcp binding'] } },

  { id: 'nat', level: 2, title: 'No internet at home', topics: ['NAT', 'Routing'],
    symptom: '<p>Since the router was replaced, nothing on the internet is reachable from home. The web server 198.51.100.80 is up.</p>',
    topo: () => natTopo({ nat: true }),
    variants: [
      { fault: t => { dev(t, 'home').nat.outside = 'eth1'; }, cause: 'NAT was set up with eth1 as the outside interface, which is the inside. Packets to the internet left untranslated with their private source address.' },
      { fault: t => { dev(t, 'home').routes = []; }, cause: 'The router had no default route to the provider. It did not know where to send anything outside its own networks.' },
      { fault: t => { dev(t, 'home').nat.masquerade = false; }, cause: 'Masquerading was off, so only port forwards were translated. Outgoing connections left with private source addresses and the answers could not find their way back.' }],
    goals: [{ text: 'pc1 fetches http://198.51.100.80/.', check: curlOk('pc1') }],
    hints: ['Look at the source address of the packets between home and isp.', 'Check the routing table and NAT settings of home.'],
    presets: { pc1: ['curl http://198.51.100.80/', 'ping -c 1 198.51.100.80'], home: ['conntrack -L', 'show ip route'] } },

  { id: 'dns', level: 1, title: '"Could not resolve host"', topics: ['DNS', 'UDP'],
    symptom: '<p><code>curl http://10.20.0.80/</code> works, but <code>curl http://web.lab/</code> fails.</p>',
    topo: () => servicesTopo(),
    variants: [
      { fault: t => { dev(t, 'client').resolver = '10.20.0.54'; }, cause: 'The client used 10.20.0.54 as its DNS server, which does not exist. The query timed out.' },
      { fault: t => { dev(t, 'dns').dns = dev(t, 'dns').dns.filter(r => r.name !== 'web.lab'); }, cause: 'The DNS server had no A record for web.lab and answered NXDOMAIN.' },
      { fault: t => { dev(t, 'r1').acl = [{ action: 'drop', proto: 'udp', port: 53, src: 'any', dst: 'any' }]; }, cause: 'A rule on r1 dropped UDP port 53. The DNS queries never reached the server.' }],
    goals: [{ text: 'client fetches http://web.lab/.', check: sim => sim.log.some(e => e.dev === 'client' && e.tag === 'dns-done' && e.data.ok && e.data.name === 'web.lab') && curlOk('client')(sim) }],
    hints: ['Try dig web.lab on the client and read the answer.', 'Is the DNS server reachable at all? Is there a record for web.lab?'],
    presets: { client: ['curl http://web.lab/', 'dig web.lab', 'dig @10.20.0.53 web.lab'], dns: ['ss -tuln'] } },

  { id: 'dnstree', level: 2, title: 'Names on the internet stopped working', topics: ['DNS', 'Resolver', 'Delegation'],
    symptom: '<p>The web server 203.0.113.80 answers <code>curl http://203.0.113.80/</code> just fine. But the client can no longer open <code>http://www.firma.lab/</code>, or cannot resolve <code>portal.partner.lab</code>, or both. The client uses the resolver 10.1.0.53 in its own network.</p>',
    topo: () => dnsTopo(),
    variants: [
      { fault: t => { dev(t, 'nic').dns = dev(t, 'nic').dns.filter(r => !(r.name === 'firma.lab' && r.type === 'NS')); }, cause: 'The TLD server of lab. had lost the delegation of firma.lab (the NS record). For the TLD, firma.lab simply did not exist: NXDOMAIN, which the resolver then also cached for 60 seconds.' },
      { fault: t => { dev(t, 'nic').dns.find(r => r.name === 'ns1.firma.lab').ip = '203.0.113.35'; }, cause: 'The glue record on the TLD server pointed to 203.0.113.35 instead of 203.0.113.53. The resolver asked a machine that does not exist, timed out and answered SERVFAIL. After the fix, the wrong glue stays in the cache of the resolver until it is flushed or expires.' },
      { fault: t => { dev(t, 'resolver').recursion.roots = '198.41.0.40'; }, cause: 'The root hints of the resolver were wrong (198.41.0.40). Without a working root server it could not start anywhere: SERVFAIL for every name it did not have cached.' },
      { fault: t => { dev(t, 'r1').acl = [{ action: 'drop', proto: 'udp', port: 53, src: '10.1.0.53', dst: 'any' }]; }, cause: 'A rule on r1 dropped DNS queries from the resolver to the internet. The client reached the resolver just fine, but the resolver could not reach a single server: SERVFAIL.' },
      { fault: t => { dev(t, 'ns1').dnsZone = 'firma.lan'; }, cause: 'ns1 was configured for the zone firma.lan instead of firma.lab. It refused every question for firma.lab (REFUSED), so the delegation was lame.' },
      { fault: t => { dev(t, 'client').resolver = '203.0.113.53'; }, cause: 'The client used ns1.firma.lab (203.0.113.53) as its DNS server instead of the resolver. ns1 is authoritative for firma.lab and answered www.firma.lab, but it is no resolver and refused everything else.' }],
    goals: [{ text: 'client opens http://www.firma.lab/.', check: sim => dnsOk('client', 'www.firma.lab')(sim) && curlOk('client')(sim) },
      { text: 'client resolves portal.partner.lab.', check: dnsOk('client', 'portal.partner.lab') }],
    hints: ['Start on the client: dig www.firma.lab shows the status (NXDOMAIN, SERVFAIL, REFUSED?) and which server answered.', 'dig +trace www.firma.lab walks the tree step by step and shows where it breaks. The log of the resolver tells the same story.', 'After a fix, think of the cache of the resolver: unbound-control flush_all.'],
    presets: { client: ['curl http://www.firma.lab/', 'dig www.firma.lab', 'dig +trace www.firma.lab', 'dig portal.partner.lab'], resolver: ['unbound-control dump_cache', 'unbound-control flush_all'] } },

  { id: 'dnsstale', level: 1, title: 'The new web server never gets visitors', topics: ['DNS', 'Caching', 'TTL'],
    symptom: '<p>Last night the web site moved to a new server with the address 203.0.113.81, the old one at .80 was switched off. This morning the client still cannot open <code>http://www.firma.lab/</code>.</p>',
    topo: () => { const t = dnsTopo(); dev(t, 'web').ifaces.eth1.ip = '203.0.113.81'; return t; },
    variants: [
      { fault: t => { dev(t, 'ns1').dns.find(r => r.name === 'www.firma.lab').ttl = 86400; dev(t, 'resolver').recursion.seed = [{ name: 'www.firma.lab', type: 'A', data: '203.0.113.80', ttl: 86400 }]; dev(t, 'ns1').dns.find(r => r.name === 'www.firma.lab').ip = '203.0.113.81'; },
        cause: 'The record had been updated, but its TTL was a whole day. The resolver had cached the old address yesterday and kept handing it out. Flushing the cache helped; next time, lower the TTL before the move.' },
      { fault: t => { dev(t, 'ns1').dns.find(r => r.name === 'www.firma.lab').ip = '203.0.113.80'; }, cause: 'Nobody had updated the record on the authoritative server ns1: www.firma.lab still pointed to the old address .80.' },
      { fault: t => { const d = dev(t, 'ns1').dns; d.find(r => r.name === 'www.firma.lab').ip = '203.0.113.81'; d.push({ name: 'www.firma.lab', type: 'A', ip: '203.0.113.80', ttl: 60 }); },
        cause: 'ns1 had two A records for www.firma.lab: the new one and the old one, which nobody deleted. Clients picked one of them, and the old server was off.' }],
    goals: [{ text: 'client opens http://www.firma.lab/ on the new server.', check: sim => sim.log.some(e => e.dev === 'client' && e.tag === 'dns-done' && e.data.name === 'www.firma.lab' && e.data.answer === '203.0.113.81') && curlOk('client')(sim) }],
    hints: ['dig www.firma.lab on the client: which address, and which TTL?', 'Compare with what the authoritative server says: dig @203.0.113.53 www.firma.lab', 'unbound-control dump_cache on the resolver shows what it remembers.'],
    presets: { client: ['curl http://www.firma.lab/', 'dig www.firma.lab', 'dig @203.0.113.53 www.firma.lab'], resolver: ['unbound-control dump_cache', 'unbound-control flush_all'] } },

  { id: 'ipv6slaac', level: 1, title: 'The PCs have no IPv6 address', topics: ['IPv6', 'SLAAC', 'Router advertisement'],
    symptom: '<p>The office was switched to dual stack yesterday. IPv4 works, but <code>ip -6 addr</code> on pc1 only shows an fe80:: address, and <code>ping -6 2001:db8:2::80</code> says "Network is unreachable".</p>',
    topo: () => ipv6Topo(),
    variants: [
      { fault: t => { dev(t, 'r1').ipv6.ra = []; }, cause: 'r1 did not send router advertisements on eth1. Without an RA the PCs got neither a prefix nor a default router, only their link-local addresses.' },
      { fault: t => { dev(t, 'r1').ipv6.ra = ['eth2']; }, cause: 'Router advertisements were turned on for eth2, the link to r2, instead of eth1 towards the LAN.' },
      { fault: t => { dev(t, 'r1').ifaces.eth1.ip6 = ['2001:db8:1::1/56']; }, cause: 'r1 had a /56 on its LAN port. SLAAC only works with a /64: the RA contained the prefix, but without permission to form addresses from it.' },
      { fault: t => { dev(t, 'pc1').ipv6.slaac = false; }, cause: 'SLAAC was turned off on pc1 (accept_ra 0). pc1 ignored every router advertisement. pc2 worked fine.' }],
    goals: [{ text: 'pc1 pings the web server over IPv6 (2001:db8:2::80).', check: pingAfterStart('pc1', '2001:db8:2::80') }],
    hints: ['rdisc6 eth1 on pc1 shows whether a router advertises anything, and what.', 'Look at the IPv6 section of r1: which ports send RAs, with which prefix length?'],
    presets: { pc1: ['ip -6 addr', 'ip -6 route', 'rdisc6 eth1', 'ping -6 -c 2 2001:db8:2::80'], pc2: ['ip -6 addr'], r1: ['show ipv6 route', 'ip -6 addr'] } },

  { id: 'ipv6route', level: 2, title: 'IPv6 stops at the router', topics: ['IPv6', 'Routing', 'NDP'],
    symptom: '<p>pc1 has its IPv6 address and pings r1 over IPv6 just fine. The web server 2001:db8:2::80 does not answer over IPv6, over IPv4 everything works.</p>',
    topo: () => ipv6Topo(),
    variants: [
      { fault: t => { dev(t, 'r2').routes = dev(t, 'r2').routes.filter(r => !String(r.dst).includes(':')); }, cause: 'r2 had no IPv6 route back to 2001:db8:1::/64. The requests reached the server, the replies died at r2.' },
      { fault: t => { dev(t, 'r1').routes.find(r => String(r.dst).includes(':')).via = '2001:db8:12::3'; }, cause: 'The IPv6 route on r1 pointed to 2001:db8:12::3, which does not exist. r1 asked for it with Neighbor Solicitations that nobody answered (address unreachable).' },
      { fault: t => { dev(t, 'web').ipv6.gw = ''; }, cause: 'The web server had a static IPv6 address but no IPv6 gateway. It could only answer inside its own network.' },
      { fault: t => { dev(t, 'r2').ipv6.enabled = false; }, cause: 'IPv6 was turned off on r2. It routed IPv4 but dropped every IPv6 packet.' }],
    goals: [{ text: 'pc1 pings 2001:db8:2::80 over IPv6.', check: pingAfterStart('pc1', '2001:db8:2::80') }],
    hints: ['traceroute -6 2001:db8:2::80 shows how far the packets get.', 'Check every router on the way, in both directions: show ipv6 route and ip -6 neigh.'],
    presets: { pc1: ['ping -6 -c 2 2001:db8:2::80', 'traceroute -6 2001:db8:2::80'], r1: ['show ipv6 route', 'ip -6 neigh'], r2: ['show ipv6 route', 'ip -6 neigh'], web: ['ip -6 route'] } },

  { id: 'ipv6dual', level: 2, title: 'www.lab is broken, but only for the new PCs', topics: ['IPv6', 'Dual stack', 'DNS'],
    symptom: '<p>Since the PCs got IPv6, <code>curl http://www.lab/</code> fails on pc1. <code>curl -4 http://www.lab/</code> still works. Old devices without IPv6 have no problem at all.</p>',
    topo: () => ipv6Topo(),
    variants: [
      { fault: t => { dev(t, 'dns').dns.find(r => r.type === 'AAAA').ip = '2001:db8:2::81'; }, cause: 'The AAAA record of www.lab pointed to 2001:db8:2::81 instead of ::80. The PCs prefer IPv6 and tried an address nobody has. IPv4 clients only asked for the A record.' },
      { fault: t => { dev(t, 'web').ifaces.eth1.ip6 = []; dev(t, 'web').ipv6.enabled = false; }, cause: 'The web server had no IPv6 at all, but DNS published an AAAA record for it. Every dual-stack client tried IPv6 first. Either give the server its IPv6 address or remove the AAAA record.' },
      { fault: t => { dev(t, 'web').ipv6.gw = '2001:db8:2::2'; }, cause: 'The IPv6 gateway of the web server was 2001:db8:2::2, a router that does not exist. The SYN arrived, but the SYN/ACK never left the server network.' }],
    goals: [{ text: 'pc1 opens http://www.lab/ over IPv6.', check: sim => sim.log.some(e => e.dev === 'pc1' && e.tag === 'tcp-done' && e.data.ok && String(e.data.dst).includes(':')) }],
    hints: ['dig www.lab AAAA and dig www.lab A on pc1: which addresses does DNS give out?', 'Does the web server answer ping -6 at that address? Look at its IPv6 configuration.'],
    presets: { pc1: ['curl http://www.lab/', 'curl -4 http://www.lab/', 'dig www.lab AAAA', 'ping -6 -c 2 2001:db8:2::80'], web: ['ip -6 addr', 'ip -6 route'] } },

  { id: 'vpn', level: 2, title: 'The new tunnel stays dark', topics: ['VPN', 'WireGuard'],
    symptom: '<p>Yesterday the two sites were connected with WireGuard between gwA and gwB. pcA still cannot reach the server srvB (10.2.0.10) at site B. Both gateways reach each other over the internet.</p>',
    topo: () => vpnTopo(),
    variants: [
      { fault: t => { dev(t, 'gwB').wg.peers[0].publicKey = wgPubKey(wgGenKey('typo')); }, cause: 'gwB had a wrong public key for gwA. gwA\'s handshake carried a key gwB did not know, and WireGuard answers strangers with silence.' },
      { fault: t => { dev(t, 'gwA').wg.peers[0].publicKey = wgPubKey(wgGenKey('old-gwB')); }, cause: 'gwA used an old public key for gwB. The handshake was encrypted for a key gwB does not have, so gwB could not read it and stayed silent.' },
      { fault: t => { dev(t, 'gwA').wg.peers[0].endpoint = '203.0.113.1:51821'; }, cause: 'gwA sent its handshakes to port 51821, gwB listens on 51820. gwB answered with ICMP port unreachable.' },
      { fault: t => { dev(t, 'gwB').wg.peers[0].allowedIps = '10.99.0.1/32'; }, cause: 'The allowed IPs of gwA on gwB only contained 10.99.0.1/32. gwB decrypted the pings but dropped them, because 10.1.0.10 was not allowed from that peer, and had no route back into the tunnel.' },
      { fault: t => { dev(t, 'gwA').wg.peers[0].allowedIps = '10.99.0.2/32'; }, cause: 'gwA did not have 10.2.0.0/24 in the allowed IPs of gwB. Without a route into wg0, pcA\'s packets went unencrypted to the provider, which has no route to private networks.' },
      { fault: t => { dev(t, 'isp').acl = [{ action: 'drop', proto: 'udp', port: 51820, src: 'any', dst: 'any' }]; }, cause: 'The provider dropped UDP port 51820. No handshake ever arrived. A different listen port, or a talk with the provider, helps.' }],
    goals: [{ text: 'pcA pings srvB (10.2.0.10).', check: pingAfterStart('pcA', '10.2.0.10') }],
    hints: ['wg show on both gateways: is there a latest handshake?', 'Read the log of the gateways: WireGuard drops silently, but the simulator tells you why.', 'Compare the keys: the public key gwA shows for itself must be the one gwB has for gwA, and the other way round.'],
    presets: { pcA: ['ping -c 2 10.2.0.10', 'traceroute 10.2.0.10'], gwA: ['wg show', 'ip route'], gwB: ['wg show', 'ip route'], isp: ['ip route'] } },

  { id: 'bgpebgp', level: 1, title: 'The partner network stays invisible', topics: ['BGP', 'eBGP'],
    symptom: '<p>AS 65001 (r1) and the partner AS 65002 (r2) want to exchange their networks with BGP. pc1 still cannot reach the server srv2 (10.2.0.10) in the partner network.</p>',
    topo: () => bgpPairTopo(),
    variants: [
      { fault: t => { dev(t, 'r2').bgp.neighbors[0].remoteAs = 65003; }, cause: 'r2 expected its neighbor in AS 65003. r1 announced AS 65001 in its OPEN, r2 answered with a NOTIFICATION "Bad Peer AS" and closed the session, again and again.' },
      { fault: t => { dev(t, 'r2').bgp.neighbors[0].ip = '10.0.12.5'; }, cause: 'r2 had 10.0.12.5 as its neighbor instead of 10.0.12.1. It refused the connection of r1, which came from an address it did not know.' },
      { fault: t => { dev(t, 'r2').bgp.networks = ['10.2.0.0/16']; }, cause: 'r2 announced 10.2.0.0/16, but only 10.2.0.0/24 is in its routing table. A network statement needs an exact match, so r2 announced nothing at all. The session was up the whole time.' },
      { fault: t => { dev(t, 'r1').bgp.neighbors[0].ip = '10.2.0.1'; }, cause: 'r1 had the LAN address of r2 (10.2.0.1) as its neighbor. That address is not directly connected, and eBGP only talks to directly connected neighbors unless ebgp-multihop is set.' }],
    goals: [{ text: 'pc1 pings srv2 (10.2.0.10).', check: pingAfterStart('pc1', '10.2.0.10') }],
    hints: ['show ip bgp summary on both routers: which state, and what does the last error say?', 'If the session is Established: show ip bgp. Which networks are announced?'],
    presets: { pc1: ['ping -c 2 10.2.0.10'], r1: ['show ip bgp summary', 'show ip bgp'], r2: ['show ip bgp summary', 'show ip bgp'] } },

  { id: 'bgpibgp', level: 2, title: 'The branch has no internet', topics: ['BGP', 'iBGP', 'OSPF'],
    symptom: '<p>In AS 65001, r1 is connected to the provider. Behind r3, pc3 cannot reach the web server 198.51.100.80 on the internet. OSPF inside the AS is up.</p>',
    topo: () => ibgpTopo(),
    variants: [
      { fault: t => { for (const n of dev(t, 'r1').bgp.neighbors) n.nextHopSelf = false; }, cause: 'r1 passed the provider routes on without next-hop-self. r3 got the next hop 192.0.2.1, which OSPF does not know: the route was inaccessible.' },
      { fault: t => { dev(t, 'r3').bgp.neighbors.find(n => n.ip === '10.255.0.1').updateSource = ''; dev(t, 'r2').bgp.neighbors.find(n => n.ip === '10.255.0.3').ip = '10.255.0.33'; }, cause: 'r3 opened its iBGP session to r1 from its interface address instead of its loopback (update-source missing), so r1 refused it. And r2 had a typo in the address of r3, so r3 had no second way to learn the routes.' },
      { fault: t => { dev(t, 'r3').bgp.networks = []; }, cause: 'r3 did not announce its network 10.3.0.0/24. The requests reached the web server, but the provider had no route back to pc3.' },
      { fault: t => { delete dev(t, 'r1').ospf.ifaces.lo; }, cause: 'r1 did not put its loopback 10.255.0.1 into OSPF. The other routers had no route to it, so no iBGP session to r1 could come up.' },
      { fault: t => { dev(t, 'isp').bgp.neighbors[0].remoteAs = 65002; }, cause: 'The provider had AS 65002 configured for us instead of 65001. Its NOTIFICATION "Bad Peer AS" closed the eBGP session, so no internet route ever reached AS 65001.' }],
    goals: [{ text: 'pc3 pings the web server 198.51.100.80.', check: pingAfterStart('pc3', '198.51.100.80') }],
    hints: ['Follow the routes: does r1 have 198.51.100.0/24? Does r3? Does the provider know 10.3.0.0/24?', 'show ip bgp on r3 tells you whether a route is there but inaccessible.', 'iBGP sessions run between the loopbacks: are they reachable via OSPF, and do the sessions start from them?'],
    presets: { pc3: ['ping -c 2 198.51.100.80', 'traceroute 198.51.100.80'], r1: ['show ip bgp summary', 'show ip bgp'], r3: ['show ip bgp summary', 'show ip bgp', 'show ip route'], isp: ['show ip bgp summary', 'show ip bgp'] } },

  { id: 'bgppolicy', level: 3, title: 'Everything leaves through the expensive provider', topics: ['BGP', 'Local preference', 'Policy'],
    symptom: '<p>Our AS 65001 has two providers. Provider 2 (at r3) is much cheaper, and all outgoing traffic is supposed to use it. A traceroute from pc2 to the web server 198.51.100.80 still goes through r1 and provider 1.</p>',
    topo: () => bgpMultiTopo(),
    variants: [
      { fault: () => {}, cause: 'Nobody had set a policy. With equal local preference, the shorter AS path via provider 1 won. Local preference 200 on r3 for the routes of provider 2 changes that for the whole AS.' },
      { fault: t => { dev(t, 'r3').bgp.neighbors.find(n => n.ip === '10.255.0.2').localPref = 200; }, cause: 'The local preference 200 was set on the iBGP neighbor r2, not on provider 2 (192.0.2.5). It changed nothing, because r2 does not send r3 any provider route.' },
      { fault: t => { dev(t, 'r3').bgp.neighbors.find(n => n.ip === '192.0.2.5').localPref = 200; dev(t, 'r1').bgp.neighbors.find(n => n.ip === '192.0.2.1').localPref = 300; }, cause: 'r3 had local preference 200 for provider 2, but somebody had set 300 on r1 for provider 1 earlier. The highest value wins in the whole AS.' }],
    goals: [{ text: 'A traceroute from pc2 to 198.51.100.80 goes through r3 (10.0.23.3).', check: sim => sim.log.some(e => e.dev === 'pc2' && e.tag === 'trace-done' && e.data.reached && e.data.path.includes('10.0.23.3')) }],
    hints: ['show ip bgp 198.51.100.0/24 on r2 shows both paths and why one is the best.', 'Local preference is set per neighbor, for the routes received from it. Check all neighbors of r1 and r3.'],
    presets: { pc2: ['traceroute 198.51.100.80'], r2: ['show ip bgp 198.51.100.0/24'], r1: ['show ip bgp 198.51.100.0/24'], r3: ['show ip bgp 198.51.100.0/24'] } },

  { id: 'evpn', level: 3, title: 'The new rack stays alone', topics: ['EVPN', 'BGP', 'VXLAN'],
    symptom: '<p>A new rack with vtep3 was added to the EVPN fabric yesterday. srv1 and srv2 reach each other in VNI 10010, but nobody reaches srv3 (192.168.10.13).</p>',
    topo: () => evpnTopo(),
    variants: [
      { fault: t => { dev(t, 'vtep3').vxlans[0].vni = 10030; }, cause: 'vtep3 put its servers into VNI 10030 instead of 10010. Its type 3 route was for a VNI nobody else had, so the other VTEPs ignored it.' },
      { fault: t => { for (const n of dev(t, 'spine').bgp.neighbors) n.rrClient = false; }, cause: 'The spine was not a route reflector. Over iBGP it did not pass the routes of one VTEP on to the others (iBGP split horizon), so no VTEP learned about any other.' },
      { fault: t => { dev(t, 'spine').bgp.neighbors.find(n => n.ip === '10.255.0.3').evpn = false; }, cause: 'The spine had not activated the EVPN address family towards vtep3. The session was up, but only IPv4 routes were exchanged with it.' },
      { fault: t => { dev(t, 'vtep3').routes = []; }, cause: 'vtep3 had no underlay route to the loopback of the spine. Its BGP session could never come up.' },
      { fault: t => { dev(t, 'vtep3').vxlans[0].evpn = false; }, cause: 'The segment on vtep3 was not marked for EVPN. vtep3 had BGP, but announced no type 3 route and used an empty static flood list.' }],
    goals: [{ text: 'srv1 pings srv3 (192.168.10.13).', check: pingAfterStart('srv1', '192.168.10.13') }, { text: 'srv2 pings srv3.', check: pingAfterStart('srv2', '192.168.10.13') }],
    hints: ['show ip bgp summary on vtep3 and on the spine: are the sessions up, and how many EVPN routes come in?', 'show vxlan on vtep1: is 10.255.0.3 in the flood list? show bgp l2vpn evpn shows which type 3 routes exist.'],
    presets: { srv1: ['ping -c 2 192.168.10.13'], vtep1: ['show vxlan', 'show bgp l2vpn evpn'], vtep3: ['show ip bgp summary', 'show vxlan', 'ip route'], spine: ['show ip bgp summary'] } },

  { id: 'ospf', level: 2, title: 'One site is missing from the map', topics: ['OSPF'],
    symptom: '<p>Three sites run OSPF. pc1 cannot reach the server srv3 at site 3.</p>',
    topo: () => ospfTopo(),
    variants: [
      { fault: t => { dev(t, 'o3').ospf.ifaces.eth3.enabled = false; }, cause: 'o3 did not have OSPF enabled on eth3, so it never advertised the network 10.3.0.0/24 of srv3.' },
      { fault: t => { dev(t, 'o3').ospf.timers = 'standard'; }, cause: 'o3 used the standard timers (hello 10, dead 40) while its neighbors used 1 and 4. The hellos were ignored and o3 had no neighbors.' },
      { fault: t => { dev(t, 'o3').ospf.ifaces.eth1.passive = true; dev(t, 'o3').ospf.ifaces.eth2.passive = true; }, cause: 'Both uplinks of o3 were set to passive. Passive interfaces send no hellos, so o3 never formed an adjacency.' }],
    goals: [{ text: 'pc1 reaches srv3 (10.3.0.10).', check: pingAfterStart('pc1', '10.3.0.10') }, { text: 'pc2 reaches srv3 too.', check: pingAfterStart('pc2', '10.3.0.10') }],
    hints: ['show ip ospf neighbor on each router.', 'Does 10.3.0.0/24 appear in show ip ospf database?'],
    presets: { pc1: ['ping -c 1 10.3.0.10'], pc2: ['ping -c 1 10.3.0.10'], o1: ['show ip route', 'show ip ospf database'], o3: ['show ip ospf neighbor', 'show ip ospf interface'] } },

  { id: 'vrrp', level: 3, title: 'The failover test failed', topics: ['VRRP', 'OSPF'],
    symptom: '<p>ra and rb should share the gateway 10.0.0.1. In the failover test, the network went down as soon as ra lost its LAN cable.</p>',
    topo: () => vrrpTopo(),
    variants: [
      { fault: t => { dev(t, 'rb').vrrp[0].ifname = 'eth2'; }, cause: 'rb had its VRRP group on the uplink eth2 instead of the LAN interface eth1. On the LAN, only ra was in the group, and nobody took over when it failed.' },
      { fault: t => { dev(t, 'rb').ospf.ifaces.eth1.enabled = false; }, cause: 'rb did not advertise the LAN 10.0.0.0/24 via OSPF. After the failover, core had no way back to the hosts.' },
      { fault: t => { dev(t, 'rb').vrrp = []; }, cause: 'rb was not part of the VRRP group at all. When ra failed, nobody answered for 10.0.0.1 any more.' }],
    goals: [{ text: 'Run a long ping from pc1 to srv (10.50.0.5) and disconnect ra\'s cable to sw1 while it runs: the ping continues.',
      check: sim => { const cut = sim.log.find(e => e.tag === 'link-down' && /ra eth1/.test(e.text)); return !!cut && sim.log.some(e => e.seq > cut.seq && e.t - cut.t > 2000 && e.t - cut.t < 8000 && e.dev === 'pc1' && e.tag === 'echo-reply-received'); } }],
    hints: ['Compare show vrrp on ra and rb.', 'After the failover: does core still know a route to 10.0.0.0/24?'],
    presets: { pc1: ['ping -c 40 10.50.0.5', 'ip neigh'], ra: ['show vrrp', 'ip link set eth1 down', 'ip link set eth1 up'], rb: ['show vrrp', 'show ip ospf interface'], core: ['show ip route'] } },

  { id: 'slow', level: 2, title: 'The web page is painfully slow', topics: ['Packet loss', 'TCP'],
    symptom: '<p>Fetching the web page sometimes takes seconds, pings show strange gaps. The servers are idle.</p>',
    topo: () => servicesTopo(),
    variants: [
      { fault: t => { link(t, 'r1', 'sw1').loss = 30; }, cause: 'The link between r1 and sw1 lost 30 % of all frames, a broken cable or port. TCP retransmitted, which made everything slow. Pings simply showed losses.' },
      { fault: t => { link(t, 'client', 'r1').loss = 25; link(t, 'client', 'r1').delay = 150; }, cause: 'The link between client and r1 had 25 % packet loss and 150 ms latency, like a bad wireless connection.' }],
    goals: [{ text: 'Find the bad link and repair it (no more loss).', check: sim => sim.topo.links.every(l => !(Number(l.loss) > 0)) },
      { text: 'Then fetch http://web.lab/ from the client.', check: sim => sim.topo.links.every(l => !(Number(l.loss) > 0)) && curlOk('client')(sim) }],
    hints: ['Ping the devices one hop after the other and compare the losses.', 'The log shows "Frame lost on the link" for every lost frame. Click a cable to see its properties.'],
    presets: { client: ['ping -c 20 10.10.0.1', 'ping -c 20 10.20.0.80', 'curl http://web.lab/'] } },

  { id: 'mtu', level: 3, title: 'Small pages load, large ones hang', topics: ['MTU', 'PMTUD', 'TCP'],
    symptom: '<p>The connection to the web server is established, but the page never arrives. Ping works.</p>',
    topo: () => tcpPathTopo({ fwAcl: [{ action: 'drop', proto: 'icmp', src: 'any', dst: 'any' }] }),
    variants: [
      { fault: () => {}, cause: 'fw dropped all ICMP, including "Fragmentation Needed". The web server never learned that the path only fits 1400 bytes (PMTUD blackhole). The fix: allow ICMP type 3, or MSS clamping on a router before the narrow link.' },
      { fault: t => { dev(t, 'fw').acl = [{ action: 'allow', proto: 'icmp', icmpType: 8, src: 'any', dst: 'any' }, { action: 'allow', proto: 'icmp', icmpType: 0, src: 'any', dst: 'any' }, { action: 'drop', proto: 'icmp', src: 'any', dst: 'any' }]; },
        cause: 'fw only let ping through and dropped every other ICMP message, including "Fragmentation Needed" (type 3). PMTUD could not work.' }],
    goals: [{ text: 'client fetches http://10.0.2.80/ completely.', check: curlOk('client') }],
    hints: ['Which link has the smallest MTU?', 'Which ICMP message would tell the server to send smaller segments, and does it arrive?'],
    presets: { client: ['curl http://10.0.2.80/', 'ping -c 1 -M do -s 1472 10.0.2.80'], fw: ['show ip route'] } }
];

/** Build the broken network of a challenge variant */
export function challengeTopo(c, variant) {
  const t = c.topo();
  c.variants[variant % c.variants.length].fault(t);
  return t;
}
__PACKETPILOT_FILE_END__
  mkdir -p "$W/js"
  cat > "$W/js/cli.js" <<'__PACKETPILOT_FILE_END__'
// Small command line per device, modeled on iproute2 and FRR
import { isIp, parseCidr, isIp6, isAnyIp, parseCidr6, norm6, isLinkLocal6 } from './net.js';
import { PORTS } from './engine.js';
import { resolverOf, fqdn } from './dns.js';
import { wgPubKey, wgGenKey } from './vpn.js';

const pad = (s, n) => String(s).padEnd(n);

export function helpFor(dev) {
  const l = [];
  if (dev.l3) l.push(
    'ping <ip> [-c count] [-s size] [-M do|dont] [-t ttl]',
    'traceroute <ip>',
    'ip addr               show addresses (also: ip -br a)',
    'ip route              routing table (kernel)',
    'ip route get <ip>     which route does a packet take?',
    'ip route add <net> via <ip>   add a static route',
    'ip route del <net>    remove a static route',
    'ip neigh              ARP table',
    'ip neigh flush        flush the ARP table',
    'arping [-U|-A|-D] [-c n] <ip>   ARP request, gratuitous ARP (-U/-A), duplicate address check (-D)',
    'curl http://<ip>[:port]/         fetch HTTP over TCP',
    'nc -zv <ip> <port>    check whether a TCP port is open',
    'nc -u <ip> <port>     send a UDP datagram',
    'dig [@server] <name> [A|AAAA|NS|CNAME]   DNS query over UDP 53',
    'dig +trace <name>     follow the delegation from the root yourself',
    'dig +norec / +short   no recursion wanted / only the answer',
    'curl http://<name>/   DNS first, then TCP (DNS server in the configuration)',
    'ss -tan / ss -tuln    TCP connections / open ports',
    'ping -6 <addr|name> / ping6   ping over IPv6 (link-local: fe80::1%eth1)',
    'ip -6 addr / route / neigh     IPv6 addresses, routes, neighbor cache',
    'ip -6 addr add 2001:db8::1/64 dev eth1   add an IPv6 address',
    'ip -6 route add <net>|default via <addr> [dev eth1]   static IPv6 route',
    'traceroute -6 <addr>  path over IPv6');
  if (dev.type === 'router') l.push(
    'ip link add link eth1 name eth1.10 type vlan id 10   create a subinterface',
    'ip addr add 10.10.0.1/24 dev eth1.10   set an address',
    'ip link del eth1.10   delete a subinterface');
  l.push('ip link set <port> down|up   disconnect or reconnect the cable on this port');
  if (dev.type === 'router') l.push('show ip route         routing table in FRR style', 'sysctl net.ipv4.ip_forward=0|1',
    'maximum-paths <n>     ECMP: how many equal paths are used (1 = off)', 'sysctl net.ipv4.fib_multipath_hash_policy=0|1   ECMP hash: addresses / with ports',
    'show bfd peers        BFD sessions and their state',
    'show ip ospf neighbor / database / interface   OSPF state', 'show vrrp             VRRP groups and who is master', 'conntrack -L          NAT translations (also: show ip nat)');
  if (dev.cfg.recursion?.enabled) l.push('unbound-control dump_cache     what the resolver has cached, with TTL left', 'unbound-control flush_all      empty the cache (flush <name>: one name)');
  if (dev.cfg.dhcpServer) l.push('show ip dhcp binding  addresses handed out by the DHCP server');
  if (dev.type === 'pc' || dev.type === 'server') l.push('dhclient [eth1]       ask for an address via DHCP (-r releases it)', 'rdisc6 [eth1]         ask the routers for their advertisement (IPv6)');
  if (dev.type === 'router') l.push('show ipv6 route / show ipv6 neighbors   IPv6 state in FRR style');
  if (dev.bgp) l.push('show ip bgp summary   BGP neighbors, states, prefixes', 'show ip bgp [prefix]  BGP table: all paths, the best marked with >',
    'show ip bgp neighbors <ip> advertised-routes | received-routes', 'clear ip bgp * | <ip>   reset BGP sessions');
  if (dev.wg) l.push('wg show               WireGuard: keys, peers, endpoints, latest handshake', 'wg genkey / wg pubkey <key>   make a key pair');
  if (dev.bridge) l.push('bridge fdb            MAC table (also: show mac address-table)', 'bridge fdb flush      flush the MAC table');
  if (dev.type === 'switch') l.push('show spanning-tree    STP status: root, roles, states',
    'spanning-tree on|off  turn STP on or off',
    'spanning-tree mode stp|rstp        classic (802.1D) or rapid (802.1w)',
    'spanning-tree priority <0-61440>   bridge priority (multiples of 4096)',
    'spanning-tree portfast <port> on|off   port as edge port',
    'spanning-tree cost <port> <cost>       port cost');
  if (dev.type === 'vtep') l.push('show vxlan            VXLAN segments, flood lists, MTU', 'show evpn [mac]       EVPN: remote VTEPs per VNI, MAC table', 'show bgp l2vpn evpn   EVPN routes (type 2 and type 3)');
  l.push('clear                 clear the console');
  return l;
}

export function runCommand(dev, line) {
  const p = line.trim().split(/\s+/).filter(Boolean);
  if (!p.length) return;
  const sim = dev.sim;
  const say = t => dev.print(t);
  const cmd = p.join(' ');
  const own = ['ping', 'ping6', 'traceroute', 'traceroute6', 'arping', 'curl', 'nc', 'dig', 'nslookup', 'dhclient', 'rdisc6'];
  if (!own.includes(p[0]) || !dev.l3) say(`$ ${cmd}`);
  try {
    if (p[0] === 'help' || p[0] === '?') return helpFor(dev).forEach(say);
    if (p[0] === 'clear' && !p[1]) { dev.consoleLines.length = 0; sim.emit('console', { devId: dev.id, clear: true }); return; }

    if (p[0] === 'ping' || p[0] === 'ping6') {
      const p0 = p[0];
      if (!dev.l3) return say('This device has no IP address. Pings can be sent from PCs, servers, routers and VTEPs.');
      const o = { count: 4 }; let dst = null, family = p0 === 'ping6' ? 6 : 0;
      for (let i = 1; i < p.length; i++) {
        if (p[i] === '-6' || p[i] === '-4') family = Number(p[i][1]);
        else if (p[i] === '-c') o.count = Math.min(100, Math.max(1, Number(p[++i]) || 4));
        else if (p[i] === '-s') o.size = Math.min(9000, Math.max(0, Number(p[++i]) || 56));
        else if (p[i] === '-M') o.df = p[++i] === 'do';
        else if (p[i] === '-t') o.ttl = Math.min(255, Math.max(1, Number(p[++i]) || 64));
        else dst = p[i];
      }
      if (dst && !isAnyIp(dst) && /^[a-zA-Z][a-zA-Z0-9.-]*$/.test(dst)) {
        say(`$ ${cmd}`);
        if (!dev.resolve) return say(`ping: ${dst}: no DNS on this device, use an address`);
        return dev.resolve(dst, ip => ip ? dev.ping(ip, { ...o, noEcho: true }) : say(`ping: ${dst}: Name or service not known`), { family });
      }
      if (!isAnyIp(dst)) return say('ping: please enter a valid address, e.g. ping 10.0.0.2 or ping 2001:db8::1');
      if (family === 4 && isIp6(dst)) return say(`ping: ${dst}: Address family for hostname not supported`);
      dev.ping(isIp6(dst) ? norm6(dst) + (dst.includes('%') ? '%' + dst.split('%')[1] : '') : dst, o); return;
    }
    if (p[0] === 'traceroute' || p[0] === 'tracert' || p[0] === 'traceroute6') {
      if (!dev.l3) return say('This device has no IP address.');
      const dst = p.find((x, i) => i > 0 && isAnyIp(x));
      if (!dst) return say('traceroute: please enter an IPv4 or IPv6 address.');
      dev.traceroute(isIp6(dst) ? norm6(dst) : dst); return;
    }
    if (p[0] === 'ip' && dev.l3 && p.includes('-6')) return ip6Command(dev, p.filter(x => x !== '-6'), say);
    if (p[0] === 'ip' && dev.l3 && p[1] !== 'link') {
      const sub = p.filter(x => !x.startsWith('-'))[1] || '';
      const brief = p.includes('-br');
      if (/^a(ddr|ddress)?$/.test(sub)) {
        const act = p.filter(x => !x.startsWith('-'))[2];
        if (act === 'add' || act === 'del') {
          const c = parseCidr(p[p.indexOf(act) + 1] || ''), ifn = p[p.indexOf('dev') + 1];
          const raw = (p[p.indexOf(act) + 1] || '').split('/');
          if (!c || p.indexOf('dev') < 0 || !dev.cfg.ifaces?.[ifn]) return say(`Syntax: ip addr ${act} 10.0.0.1/24 dev eth1`);
          if (act === 'add') { dev.cfg.ifaces[ifn].ip = raw[0]; dev.cfg.ifaces[ifn].prefix = c.len; }
          else dev.cfg.ifaces[ifn].ip = '';
          sim.record(dev, 'info', `Address ${raw[0]}/${c.len} ${act === 'add' ? 'set on ' + ifn : 'removed from ' + ifn}`, { tag: 'addr-changed', data: { ifname: ifn } });
          sim.configChanged(dev.id);
          return say('OK');
        }
        const names = Object.keys(dev.cfg.ifaces || {});
        for (const n of names) {
          const c = dev.cfg.ifaces[n];
          const mtu = dev.l3.mtu(n);
          const up = n === 'lo' || dev.l3.linkUp(n);
          const label = c.parent ? `${n}@${c.parent}` : n + (c.vlan ? '.' + c.vlan : '');
          const eff = dev.l3.ifaces().find(i => i.name === n);
          const addr = eff ? `${eff.ip}/${eff.prefix}` : '';
          if (brief) say(`${pad(label, 14)}${pad(up ? 'UP' : 'DOWN', 8)}${addr}${c.dhcp && !addr ? '(DHCP, no lease)' : ''}`);
          else {
            say(`${label}: <${up ? 'UP,LOWER_UP' : 'NO-CARRIER'}> mtu ${mtu}`);
            if (n !== 'lo') say(`    link/ether ${dev.mac(n)}${c.vlan ? `  (${c.parent ? '802.1Q id' : 'VLAN tag'} ${c.vlan})` : ''}`);
            if (addr) say(`    inet ${addr}${c.dhcp ? ` dynamic valid_lft ${dev.l3.lease?.lease ?? 0}sec` : ''}`);
            else if (c.dhcp) say('    (DHCP: no lease yet, try dhclient)');
            for (const g of dev.vrrp?.table() || []) if (g.ifname === n && g.state === 'master') say(`    inet ${g.vip}/32 (VRRP ${g.vrid} virtual address)`);
            for (const a of dev.l3.v6.ifnames().includes(n) ? dev.l3.v6.addrs(n) : []) say(inet6Line(a));
          }
        }
        return;
      }
      if (/^r(oute)?$/.test(sub)) {
        const act = p[2];
        if (act === 'get') {
          const dst = p[3];
          if (!isIp(dst)) return say('Please enter an IP address.');
          if (dev.l3.isOwn(dst)) return say(`local ${dst} dev lo  (own address)`);
          const r = dev.l3.lookup(dst);
          if (!r) return say('RTNETLINK answers: Network is unreachable');
          const pm = dev.l3.pmtu.get(dst);
          return say(`${dst}${r.via ? ' via ' + r.via : ''} dev ${r.dev} src ${dev.l3.ifIp(r.dev)}   [match: ${r.net}/${r.len}]${pm ? `\n    cache mtu ${pm}` : ''}`);
        }
        if (act === 'add' || act === 'del' || act === 'delete') {
          if (dev.type === 'pc' || dev.type === 'server') {
            if (p[3] === 'default' && act === 'add') { const via = p[p.indexOf('via') + 1]; if (!isIp(via)) return say('Syntax: ip route add default via <ip>'); dev.cfg.gw = via; say('OK'); sim.configChanged(dev.id); return; }
            if (p[3] === 'default') { dev.cfg.gw = ''; say('OK'); sim.configChanged(dev.id); return; }
          }
          const net = parseCidr(p[3]);
          if (!net) return say('Syntax: ip route add 10.0.0.0/24 via 192.168.1.1');
          const key = `${net.net}/${net.len}`;
          dev.cfg.routes ??= [];
          if (act === 'add') {
            // Several next hops (ECMP): ip route add 10.0.0.0/24 nexthop via A nexthop via B
            const vias = p.map((x, i) => x === 'via' ? p[i + 1] : null).filter(Boolean);
            const via = vias[0];
            if (!vias.length || !vias.every(isIp)) return say('Syntax: ip route add 10.0.0.0/24 via 192.168.1.1   (several: nexthop via A nexthop via B)');
            if (dev.cfg.routes.some(r => parseCidr(r.dst) && `${parseCidr(r.dst).net}/${parseCidr(r.dst).len}` === key)) return say('RTNETLINK answers: File exists');
            const di = p.findIndex(x => x === 'distance' || x === 'metric');
            const distance = di >= 0 ? Number(p[di + 1]) : 1;
            if (!(distance >= 1 && distance <= 255)) return say('The distance must be between 1 and 255.');
            for (const v of vias) dev.cfg.routes.push({ dst: key, via: v, ...(distance !== 1 ? { distance } : {}), ...(p.includes('bfd') ? { bfd: true } : {}) });
            if (!dev.l3.routes().find(r => r.proto === 'S' && `${r.net}/${r.len}` === key)?.dev) say(`Note: next hop ${via} is not in any directly connected network, the route is inactive.`);
          } else {
            const before = dev.cfg.routes.length;
            dev.cfg.routes = dev.cfg.routes.filter(r => { const c = parseCidr(r.dst); return !c || `${c.net}/${c.len}` !== key; });
            if (before === dev.cfg.routes.length) return say('RTNETLINK answers: No such process');
          }
          sim.record(dev, 'info', `Route ${key} ${act === 'add' ? 'added' : 'removed'}`, { tag: 'route-changed', data: { dst: key, act } });
          sim.configChanged(dev.id);
          return say('OK');
        }
        // Routes with several next hops (ECMP) are shown like Linux does: one line per nexthop
        const groups = [];
        for (const r of dev.l3.routes()) {
          const g = groups.find(x => x[0].proto === r.proto && x[0].net === r.net && x[0].len === r.len && r.proto !== 'C' && r.dev && x[0].dev);
          if (g) g.push(r); else groups.push([r]);
        }
        for (const g of groups) {
          const r = g[0], dst = r.len === 0 ? 'default' : r.net + '/' + r.len;
          const proto = r.proto === 'O' ? ' proto ospf' : r.dhcp ? ' proto dhcp' : '';
          if (r.proto === 'C') { say(`${dst} dev ${r.dev} proto kernel scope link src ${r.src}`); continue; }
          if (g.length > 1) { say(`${dst}${proto}${r.metric ? ' metric ' + r.metric : ''}`); for (const x of g) say(`\tnexthop via ${x.via} dev ${x.dev} weight 1`); continue; }
          if (!r.dev) { say(`${dst} via ${r.via}  (inactive: ${r.bfdDown ? 'BFD says the next hop is down' : 'next hop unreachable'})`); continue; }
          say(`${dst} via ${r.via} dev ${r.dev}${proto}${r.metric ? ' metric ' + r.metric : ''}${r.bfd ? '  (BFD watched)' : ''}`);
        }
        return;
      }
      if (/^n(eigh|eighbor)?$/.test(sub)) {
        if (p[2] === 'flush') { dev.l3.arp.clear(); sim.record(dev, 'info', 'ARP table flushed', { tag: 'arp-flushed' }); return say('OK'); }
        const t = dev.l3.arpTable(), t6 = dev.l3.v6.neighborTable();
        if (!t.length && !t6.length) return say('(empty)');
        for (const e of t) say(`${e.ip} dev ${e.ifname}${e.mac ? ' lladdr ' + e.mac : ''} ${e.state}`);
        for (const e of t6) say(`${e.ip} dev ${e.ifname}${e.mac ? ' lladdr ' + e.mac : ''}${e.router ? ' router' : ''} ${e.state}`);
        return;
      }
      return say('Unknown ip command. Type help.');
    }
    if (p[0] === 'ip' && p[1] === 'link') {
      const act = p[2];
      if (act === 'set') {
        const port = p[3], st = p[4];
        const l = sim.linkAt(dev.id, port);
        if (!l || !['up', 'down'].includes(st)) return say(l ? 'Syntax: ip link set eth1 down|up' : `${port || '?'}: no cable on this port`);
        sim.setLinkUp(l, st === 'up');
        return say('OK');
      }
      if (act === 'add' && dev.type === 'router') {
        const m = cmd.match(/ip link add link (\S+) name (\S+) type vlan id (\d+)/);
        if (!m) return say('Syntax: ip link add link eth1 name eth1.10 type vlan id 10');
        const [, par, name, vid] = m;
        if (!PORTS.router.includes(par)) return say(`${par}: not a physical interface`);
        if (dev.cfg.ifaces[name]) return say('RTNETLINK answers: File exists');
        const v = Number(vid);
        if (!(v >= 1 && v <= 4094)) return say('VLAN ID must be between 1 and 4094');
        if (Object.values(dev.cfg.ifaces).some(c => c.parent === par && Number(c.vlan) === v)) return say(`${par} already has a subinterface for VLAN ${v}`);
        dev.cfg.ifaces[name] = { parent: par, vlan: v, ip: '', prefix: 24 };
        sim.record(dev, 'info', `Subinterface ${name} created on ${par} for VLAN ${v}`, { tag: 'subif-added', data: { name, vlan: v } });
        sim.configChanged(dev.id);
        return say('OK');
      }
      if ((act === 'del' || act === 'delete') && dev.type === 'router') {
        const name = p[3];
        if (!dev.cfg.ifaces?.[name]?.parent) return say('Only subinterfaces can be deleted.');
        delete dev.cfg.ifaces[name];
        sim.configChanged(dev.id);
        return say('OK');
      }
      for (const port of PORTS[dev.type]) {
        const l = sim.linkAt(dev.id, port);
        say(`${port}: <${l ? (l.up ? 'UP,LOWER_UP' : 'DOWN') : 'NO-CARRIER'}> mtu ${l ? l.mtu : 1500}`);
      }
      return;
    }
    if (p[0] === 'arping') {
      if (!dev.l3) return say('This device has no IP address.');
      const o = { mode: 'normal' }; let ip = null;
      for (let i = 1; i < p.length; i++) {
        if (p[i] === '-U') o.mode = 'gratuitous';
        else if (p[i] === '-A') o.mode = 'reply';
        else if (p[i] === '-D') o.mode = 'dad';
        else if (p[i] === '-c') o.count = Math.min(10, Math.max(1, Number(p[++i]) || 1));
        else if (p[i] === '-I') o.ifname = p[++i];
        else ip = p[i];
      }
      if (!isIp(ip)) { say(`$ ${cmd}`); return say('Syntax: arping [-U|-A|-D] [-c count] [-I interface] <ip>'); }
      if (o.ifname && !dev.cfg.ifaces?.[o.ifname]) { say(`$ ${cmd}`); return say(`arping: interface ${o.ifname} does not exist`); }
      dev.arping(ip, o); return;
    }
    if (p[0] === 'curl' && dev.l3) {
      const u = p.slice(1).find(x => !x.startsWith('-')) || '';
      const m = u.match(/^(?:http:\/\/)?(\[[0-9a-fA-F:]+\]|[a-zA-Z0-9.-]+)(?::(\d+))?\/?$/);
      if (!m) { say(`$ ${cmd}`); return say('Syntax: curl http://10.0.0.10/, curl http://[2001:db8::80]/ or curl http://web.lab:8080/'); }
      const port = m[2] ? Number(m[2]) : 80;
      const host = m[1].replace(/^\[|\]$/g, '');
      const family = p.includes('-6') ? 6 : p.includes('-4') ? 4 : 0;
      if (isIp(host)) { dev.curl(host, port); return; }
      if (isIp6(host)) { dev.curl(norm6(host), port); return; }
      say(`$ ${cmd}`);
      if (!dev.resolve) return say(`curl: (6) Could not resolve host: ${host} (no DNS on this device)`);
      dev.resolve(host, ip => ip ? dev.curl(ip, port, { noEcho: true }) : say(`curl: (6) Could not resolve host: ${host}`), { family }); return;
    }
    if (p[0] === 'nc' && dev.l3) {
      const args = p.slice(1).filter(x => !x.startsWith('-'));
      const flags = p.slice(1).filter(x => x.startsWith('-')).join('');
      const [ip, port] = args; const n = Number(port);
      if (!isIp(ip) || !(n >= 1 && n <= 65535)) { say(`$ ${cmd}`); return say('Syntax: nc -zv <ip> <port>  or  nc -u <ip> <port>'); }
      if (flags.includes('u')) dev.udpSend(ip, n, 32); else dev.ncz(ip, n);
      return;
    }
    if ((p[0] === 'dig' || p[0] === 'nslookup') && dev.l3) {
      let server = null, name = null, type = 'A';
      const o = {};
      for (const x of p.slice(1)) {
        if (x.startsWith('@')) server = x.slice(1);
        else if (x === '+trace') o.trace = true;
        else if (x === '+norec' || x === '+norecurse') o.rd = false;
        else if (x === '+short') o.short = true;
        else if (/^(A|AAAA|NS|CNAME)$/i.test(x) && name) type = x.toUpperCase();
        else if (x.startsWith('-type=') || x.startsWith('-q=')) type = x.split('=')[1].toUpperCase();
        else if (isIp(x) && p[0] === 'nslookup' && name) server = x;
        else if (!x.startsWith('+') && !x.startsWith('-')) name = x;
      }
      server ??= dev.l3.resolver();
      if (!name) { say(`$ ${cmd}`); return say('Syntax: dig [@server] <name> [A|AAAA|NS|CNAME] [+trace] [+norec] [+short]   e.g. dig @10.0.2.53 web.lab'); }
      if (!isIp(server)) { say(`$ ${cmd}`); return say(';; No DNS server configured. Specify one with @<ip> or enter it in the configuration.'); }
      if (!['A', 'AAAA', 'NS', 'CNAME'].includes(type)) { say(`$ ${cmd}`); return say(`;; unsupported query type ${type}: A, AAAA, NS or CNAME`); }
      dev.dig(server, name, { ...o, type }); return;
    }
    if (p[0] === 'unbound-control' || (p[0] === 'show' && p[1] === 'dns' && p[2] === 'cache') || (p[0] === 'clear' && p[1] === 'dns')) {
      if (!dev.cfg.recursion?.enabled) return say('unbound-control: this device is not a recursive resolver (Configuration, Add a feature, Recursive resolver)');
      const r = resolverOf(dev.l3);
      const sub = p[0] === 'show' ? 'dump_cache' : p[0] === 'clear' ? 'flush_all' : p[1];
      if (sub === 'dump_cache') {
        const rows = r.dump();
        if (!rows.length) return say('(cache empty)');
        say(`${pad('Name', 26)}${pad('TTL left', 10)}${pad('Type', 7)}Data`);
        for (const e of rows) say(`${pad(fqdn(e.name), 26)}${pad(e.ttl + ' s', 10)}${pad(e.type, 7)}${e.type === 'NS' || e.type === 'CNAME' ? fqdn(e.data) : e.data}`);
        return;
      }
      if (sub === 'flush_all') { const n = r.flush(); dev.record('info', `cache flushed (${n} entr${n === 1 ? 'y' : 'ies'} removed)`, { tag: 'dns-flush' }); return say(`ok removed ${n} rrsets`); }
      if (sub === 'flush' && p[2]) { const n = r.flush(p[2]); dev.record('info', `cache entries for ${fqdn(p[2])} removed`, { tag: 'dns-flush', data: { name: p[2] } }); return say(`ok removed ${n} rrsets`); }
      return say('Syntax: unbound-control dump_cache | flush_all | flush <name>');
    }
    if (p[0] === 'show' && p[1] === 'ipv6' && dev.l3) {
      if (p[2] === 'route') return showIpv6Route(dev, say);
      if (/^neigh/.test(p[2] || '')) return ip6Command(dev, ['ip', 'neigh'], say);
      return say('Syntax: show ipv6 route | show ipv6 neighbors');
    }
    if (p[0] === 'rdisc6' && dev.l3) {
      const ifn = p[1] || 'eth1';
      if (!dev.l3.v6.on) { say(`$ ${cmd}`); return say('rdisc6: IPv6 is turned off on this device'); }
      if (!dev.l3.v6.ifnames().includes(ifn)) { say(`$ ${cmd}`); return say(`rdisc6: ${ifn}: no such IPv6 interface`); }
      dev.rdisc6(ifn); return;
    }
    if (p[0] === 'sysctl' && /^net\.ipv6\.conf\.(all|default)\.disable_ipv6=[01]$/.test(p[1] || '') && dev.cfg.ipv6) {
      dev.cfg.ipv6.enabled = p[1].endsWith('=0');
      sim.record(dev, 'info', `IPv6 ${dev.cfg.ipv6.enabled ? 'turned on' : 'turned off'}`, { tag: 'v6-toggle' });
      sim.configChanged(dev.id);
      return say(p[1].replace('=', ' = '));
    }
    if (p[0] === 'wg' && dev.wg) {
      const w = dev.cfg.wg;
      if (p[1] === 'genkey') return say(wgGenKey(dev.id + sim.time + Math.random()));
      if (p[1] === 'pubkey') return say(p[2] ? wgPubKey(p[2]) : 'Syntax: wg pubkey <private key>   (usually: wg genkey | wg pubkey)');
      if (!w.enabled || !dev.cfg.ifaces?.wg0) return say('No WireGuard interface (Configuration, Add a feature, WireGuard VPN)');
      if (p[1] === 'show' && p[3] === 'public-key') return say(wgPubKey(w.privateKey));
      const ago = s => s === null ? null : s < 60 ? `${s} second${s === 1 ? '' : 's'} ago` : `${Math.floor(s / 60)} minute${s >= 120 ? 's' : ''}, ${s % 60} seconds ago`;
      const kb = n => n < 1024 ? `${n} B` : `${(n / 1024).toFixed(2)} KiB`;
      say('interface: wg0');
      say(`  public key: ${wgPubKey(w.privateKey) || '(no private key!)'}`);
      say('  private key: (hidden)');
      say(`  listening port: ${w.listenPort || 51820}`);
      for (const x of dev.wg.table()) {
        say('');
        say(`peer: ${x.publicKey}${x.name ? '   (' + x.name + ')' : ''}`);
        say(`  endpoint: ${x.endpoint}`);
        say(`  allowed ips: ${x.allowed || '(none)'}`);
        if (x.handshake !== null) say(`  latest handshake: ${ago(x.handshake)}`);
        if (x.rx || x.tx) say(`  transfer: ${kb(x.rx)} received, ${kb(x.tx)} sent`);
        if (x.keepalive) say(`  persistent keepalive: every ${x.keepalive} seconds`);
      }
      return;
    }
    if (p[0] === 'ss' && dev.l3) {
      const f = p.slice(1).join('');
      if (f.includes('l')) {
        say(`${pad('Netid', 7)}${pad('State', 9)}${pad('Local Address:Port', 24)}Service`);
        const svcs = dev.cfg.services || [];
        if (!svcs.length) return say('(no service is listening)');
        for (const s of svcs) if (f.includes(s.proto[0]) || !/[tu]/.test(f)) say(`${pad(s.proto, 7)}${pad(s.proto === 'tcp' ? 'LISTEN' : 'UNCONN', 9)}${pad('0.0.0.0:' + s.port, 24)}${s.name || ''}`);
        return;
      }
      say(`${pad('State', 13)}${pad('Local Address:Port', 24)}Peer Address:Port`);
      const rows = [...dev.l3.tcp.values()];
      if (!rows.length) return say('(no TCP connections)');
      for (const c of rows) say(`${pad(c.state, 13)}${pad((c.local || dev.l3.srcFor(c.rip)) + ':' + c.lport, 24)}${c.rip}:${c.rport}`);
      return;
    }
    if (dev.type === 'switch' && (p[0] === 'spanning-tree' || (p[0] === 'show' && /^span/.test(p[1] || '')))) {
      const b = dev.bridge, st = dev.cfg.stp;
      if (p[0] === 'spanning-tree') {
        const change = (text, data) => { sim.record(dev, 'info', text, { tag: 'stp-config', data }); sim.configChanged(dev.id); say('OK'); };
        if (p[1] === 'on' || p[1] === 'off') { st.enabled = p[1] === 'on'; return change(`Spanning tree ${st.enabled ? 'turned on' : 'turned off'}`, { enabled: st.enabled }); }
        if (p[1] === 'mode') {
          const m = { stp: 'stp', rstp: 'rstp', 'rapid-pvst': 'rstp', ieee: 'stp', pvst: 'stp' }[p[2]];
          if (!m) return say('Syntax: spanning-tree mode stp|rstp');
          st.mode = m; return change(`Spanning tree protocol: ${m === 'rstp' ? 'RSTP (802.1w)' : 'STP (802.1D)'}`, { mode: m });
        }
        if (p[1] === 'priority') {
          const v = Number(p[2]);
          if (!(v >= 0 && v <= 61440 && v % 4096 === 0)) return say('The priority must be a multiple of 4096 between 0 and 61440.');
          st.priority = v; return change(`Bridge priority set to ${v}`, { priority: v });
        }
        if (p[1] === 'portfast' || p[1] === 'cost') {
          const port = p[2];
          if (!dev.cfg.ports[port]) return say(`${port || '?'}: unknown port`);
          if (p[1] === 'portfast') { dev.cfg.ports[port].edge = p[3] !== 'off'; return change(`${port}: PortFast ${dev.cfg.ports[port].edge ? 'on' : 'off'}`, { port }); }
          const c = Number(p[3]);
          if (!(c >= 1 && c <= 200000000)) return say('Syntax: spanning-tree cost eth1 19');
          dev.cfg.ports[port].cost = c; return change(`${port}: port cost ${c}`, { port, cost: c });
        }
        return say('Syntax: spanning-tree on|off | mode stp|rstp | priority <n> | portfast <port> on|off | cost <port> <n>');
      }
      const t = b.stpTable();
      if (!t) return say('Spanning tree is turned off. Turn it on with: spanning-tree on');
      say(`Spanning tree enabled protocol ${t.mode === 'rstp' ? 'rstp (802.1w)' : 'ieee (802.1D)'}`);
      say(`Root ID     ${t.root}${t.isRoot ? '   (this bridge is the root)' : ''}`);
      if (!t.isRoot) say(`            Cost ${t.rootCost}, root port ${t.rootPort}`);
      say(`Bridge ID   ${t.bridge}`);
      const tm = dev.bridge.timers();
      say(`Timers      Hello ${tm.hello} s, Max Age ${tm.maxAge} s`);
      say(`            Forward Delay ${tm.fwd} s`);
      say('');
      say(`${pad('Port', 5)}${pad('Role', 5)}${pad('State', 11)}${pad('Cost', 5)}${pad('ID', 6)}Type`);
      for (const r of t.ports) say(`${pad(r.port, 5)}${pad({ root: 'Root', designated: 'Desg', alternate: 'Altn', backup: 'Back', disabled: 'Disa' }[r.role], 5)}${pad(r.state, 11)}${pad(r.cost, 5)}${pad(r.id, 6)}${[t.mode === 'rstp' ? 'P2p' : '', r.edge ? 'Edge' : '', r.legacy ? 'Peer(STP)' : ''].filter(Boolean).join(' ')}`);
      return;
    }
    if (p[0] === 'arp' && dev.l3) return runCommand(dev, 'ip neigh');
    if (p[0] === 'dhclient' && dev.dhclient) {
      const ifn = p.slice(1).find(x => !x.startsWith('-')) || 'eth1';
      if (!dev.cfg.ifaces?.[ifn]) return say(`dhclient: interface ${ifn} does not exist`);
      if (p.includes('-r')) return dev.dhcpRelease(ifn);
      if (!dev.cfg.ifaces[ifn].dhcp) say(`Note: ${ifn} has a static address, switch it to DHCP in the configuration to keep the lease.`);
      dev.dhclient(ifn); return;
    }
    if ((p[0] === 'show' && p[1] === 'ip' && p[2] === 'dhcp') || (p[0] === 'dhcp' && p[1] === 'leases')) {
      if (!dev.l3) return say('This device has no IP address.');
      const ls = [...dev.l3.dhcpLeases.entries()];
      if (!dev.cfg.dhcpServer?.enabled) say('(the DHCP server is not enabled on this device)');
      say(`${pad('IP address', 16)}${pad('MAC address', 20)}State`);
      if (!ls.length) return say('(no leases)');
      for (const [mac, l] of ls) say(`${pad(l.ip, 16)}${pad(mac, 20)}${l.state}`);
      return;
    }
    if ((p[0] === 'conntrack' || (p[0] === 'show' && p[1] === 'ip' && p[2] === 'nat')) && dev.type === 'router') {
      const t = dev.l3.natTable;
      if (!dev.cfg.nat?.outside) say('(NAT is not configured: no outside interface)');
      if (!t.length) return say('(no translations)');
      const nm = { 1: 'icmp', 6: 'tcp', 17: 'udp' };
      say(`${pad('Proto', 6)}${pad('Inside', 22)}${pad('Outside', 22)}${pad('Remote', 22)}Type`);
      for (const e of t) say(`${pad(nm[e.proto] || e.proto, 6)}${pad(e.inIp + ':' + e.inPort, 22)}${pad(e.outIp + ':' + e.outPort, 22)}${pad(e.remIp + ':' + e.remPort, 22)}${e.kind}`);
      return;
    }
    if (p[0] === 'show' && p[1] === 'vrrp' && dev.type === 'router') {
      const t = dev.vrrp?.table() || [];
      if (!t.length) return say('(no VRRP groups configured)');
      for (const g of t) say(`${g.ifname} - group ${g.vrid}: ${g.state.toUpperCase()}, virtual IP ${g.vip}, virtual MAC ${g.vmac}, priority ${g.prio}${g.preempt ? ', preempt' : ''}, master ${g.master || 'unknown'}`);
      return;
    }
    if (p[0] === 'show' && p[1] === 'ip' && p[2] === 'ospf' && dev.type === 'router') {
      const o = dev.ospf;
      if (!o?.enabled) return say('OSPF is not enabled on this router.');
      if (p[3] === 'database') {
        say(`OSPF router with ID (${o.rid}), area 0.0.0.0`);
        for (const l of [...o.lsdb.values()].sort((a, b) => a.rid.localeCompare(b.rid, 'en', { numeric: true }))) {
          say(`  Router LSA ${l.rid}  seq ${l.seq}`);
          for (const k of l.links) say(k.type === 'router' ? `    neighbor ${k.rid}, cost ${k.cost}` : `    network ${k.net}/${k.len}, cost ${k.cost}`);
        }
        return;
      }
      if (p[3] === 'interface') {
        for (const i of o.ifs()) say(`${pad(i.name, 8)}${pad(i.ip + '/' + i.prefix, 20)}cost ${i.cost}${i.passive ? ', passive' : ''}, hello ${o.timers().hello} s, dead ${o.timers().dead} s`);
        return;
      }
      say(`${pad('Neighbor ID', 16)}${pad('State', 10)}${pad('Address', 16)}Interface`);
      const t = o.neighborTable();
      if (!t.length) return say('(no neighbors)');
      for (const n of t) say(`${pad(n.rid, 16)}${pad(n.state, 10)}${pad(n.ip, 16)}${n.ifname}`);
      return;
    }
    if (p[0] === 'show' && p[1] === 'ip' && p[2] === 'route' && dev.l3) {
      say('Codes: C - connected, S - static, O - OSPF, B - BGP, W - WireGuard, > - selected route, * - FIB route');
      const ad = r => r.proto === 'S' ? r.distance || 1 : r.proto === 'B' ? (r.ibgp ? 200 : 20) : { C: 0, O: 110, W: 0 }[r.proto];
      const all = dev.l3.routes();
      const sel = r => !!r.dev && !all.some(x => x !== r && x.dev && x.net === r.net && x.len === r.len && (ad(x) < ad(r) || (ad(x) === ad(r) && (x.metric || 0) < (r.metric || 0))));
      let prev = null;
      for (const r of all) {
        const mark = sel(r) ? '>*' : '  ';
        // Further next hops of the same route (ECMP) are indented like in FRR
        const more = prev && prev.proto === r.proto && prev.net === r.net && prev.len === r.len && r.proto !== 'C';
        const lead = more ? `  ${sel(r) ? '*' : ' '} ${' '.repeat(`${r.net}/${r.len}`.length + (r.proto === 'O' ? 9 : 6))}` : null;
        if (r.proto === 'C') say(`C${mark} ${r.net}/${r.len} is directly connected, ${r.dev}`);
        else if (r.proto === 'O') say(more ? `${lead}via ${r.via}, ${r.dev}` : `O${mark} ${r.net}/${r.len} [110/${r.metric}] via ${r.via}, ${r.dev}`);
        else if (r.proto === 'B') say(`B${mark} ${r.net}/${r.len} [${r.ibgp ? 200 : 20}/${r.metric || 0}] via ${r.bgpNh}${r.bgpNh !== r.via ? ` (recursive via ${r.via})` : ''}, ${r.dev}${r.ibgp ? '  (iBGP)' : ''}`);
        else if (r.proto === 'W') say(`W${mark} ${r.net}/${r.len} is directly connected, wg0 (peer ${r.peer || '?'})`);
        else say(more ? `${lead}via ${r.via}${r.dev ? ', ' + r.dev : ' inactive'}` : `S${mark} ${r.net}/${r.len} [${r.distance || 1}/0] via ${r.via}${r.dev ? ', ' + r.dev : r.bfdDown ? ' inactive (BFD down)' : ' inactive'}`);
        prev = r;
      }
      return;
    }
    if (p[0] === 'show' && (p[1] === 'bgp' || (p[1] === 'ip' && p[2] === 'bgp')) && dev.bgp) return showBgp(dev, p[1] === 'ip' ? p.slice(3) : p.slice(2), say);
    if (p[0] === 'clear' && (p[1] === 'bgp' || (p[1] === 'ip' && p[2] === 'bgp')) && dev.bgp) {
      const t = (p[1] === 'ip' ? p[3] : p[2]) || '*';
      if (t !== '*' && !dev.bgp.peers.has(t)) return say(`% No such neighbor ${t}`);
      dev.bgp.clear(t); return say(`BGP session${t === '*' ? 's' : ' ' + t} reset`);
    }
    if (p[0] === 'show' && p[1] === 'bfd' && dev.bfd) {
      const t = dev.bfd.table();
      if (!dev.cfg.bfd?.enabled) return say('BFD is off. Turn it on under Configuration (Add a feature, BFD).');
      if (!t.length) return say('No BFD peers. Mark a static route with BFD, or let BFD watch the OSPF neighbors.');
      say(`${pad('Peer', 16)}${pad('Interface', 11)}${pad('State', 7)}${pad('For', 14)}Discriminators`);
      for (const x of t) say(`${pad(x.peer, 16)}${pad(x.ifname, 11)}${pad(x.state, 7)}${pad(x.clients.join(', '), 14)}${x.myDisc}/${x.yourDisc || 0}`);
      say(`Interval ${dev.bfd.interval} ms × ${dev.bfd.mult} = detection after ${dev.bfd.interval * dev.bfd.mult} ms`);
      return;
    }
    if (p[0] === 'maximum-paths' && dev.type === 'router') {
      const n = Number(p[1]);
      if (!(n >= 1 && n <= 16)) return say('Syntax: maximum-paths <1-16>   (1 turns ECMP off)');
      dev.cfg.maxPaths = n; sim.record(dev, 'info', `ECMP: up to ${n} equal path${n === 1 ? '' : 's'}`, { tag: 'ecmp-config', data: { maxPaths: n } }); sim.configChanged(dev.id); return say('OK');
    }
    if (p[0] === 'sysctl' && dev.type === 'router' && /fib_multipath_hash_policy/.test(cmd)) {
      const m = cmd.match(/fib_multipath_hash_policy\s*=\s*([01])/);
      if (!m) return say(`net.ipv4.fib_multipath_hash_policy = ${dev.cfg.ecmpHash === 'l4' ? 1 : 0}`);
      dev.cfg.ecmpHash = m[1] === '1' ? 'l4' : 'l3';
      sim.record(dev, 'info', `ECMP hash over ${m[1] === '1' ? 'addresses and ports (layer 4)' : 'the addresses only (layer 3)'}`, { tag: 'ecmp-config', data: { hash: dev.cfg.ecmpHash } });
      sim.configChanged(dev.id); return say(`net.ipv4.fib_multipath_hash_policy = ${m[1]}`);
    }
    if (p[0] === 'sysctl' && dev.type === 'router') {
      const m = cmd.match(/ip_forward\s*=\s*([01])/);
      if (m) { dev.cfg.forwarding = m[1] === '1'; sim.record(dev, 'info', `IP forwarding ${dev.cfg.forwarding ? 'turned on' : 'turned off'}`, { tag: 'forwarding-changed', data: { on: dev.cfg.forwarding } }); sim.configChanged(dev.id); return say(`net.ipv4.ip_forward = ${m[1]}`); }
      return say(`net.ipv4.ip_forward = ${dev.cfg.forwarding !== false ? 1 : 0}`);
    }
    if ((p[0] === 'bridge' && p[1] === 'fdb') || (p[0] === 'show' && p[1] === 'mac')) {
      if (!dev.bridge) return say('This device has no bridge.');
      if (p[2] === 'flush') { dev.bridge.fdb.clear(); sim.record(dev, 'info', 'MAC table flushed', { tag: 'fdb-flushed' }); return say('OK'); }
      const t = dev.bridge.table();
      if (!t.length) return say('(empty)');
      say(`${pad('VLAN', 6)}${pad('MAC', 20)}${pad('Port', 12)}Age`);
      for (const e of t) say(`${pad(e.vid, 6)}${pad(e.mac, 20)}${pad(e.port, 12)}${e.age.toFixed(1)} s${e.remote ? '   dst ' + e.remote : ''}`);
      return;
    }
    if (p[0] === 'show' && p[1] === 'vxlan' && dev.type === 'vtep') {
      const ms = dev.maps();
      if (!ms.length) return say('(no VXLAN segments)');
      for (const m of ms) say(`vxlan${m.vni}: VNI ${m.vni} ↔ VLAN ${m.vlan}, local ${dev.localIp()}, dstport ${m.dstport || 4789}, mtu ${dev.vxlanMtu(m)}, flood ${dev.evpn.floodList(m).join(', ') || '(empty)'}${m.evpn ? ' (EVPN' + (m.arpSuppress ? ', ARP suppression' : '') + ')' : ''}`);
      return;
    }
    if (p[0] === 'show' && p[1] === 'evpn' && dev.type === 'vtep') {
      const e = dev.evpn;
      if (!e.on()) return say('EVPN is not active: turn on BGP and mark the VXLAN segments as EVPN');
      if (p[2] === 'mac') {
        say(`${pad('VNI', 8)}${pad('MAC', 20)}${pad('Type', 8)}${pad('Where', 18)}IP`);
        for (const r of e.localRoutes().filter(x => x.rt === 2)) say(`${pad(r.vni, 8)}${pad(r.mac, 20)}${pad('local', 8)}${pad('this VTEP', 18)}${r.ip || ''}`);
        for (const r of e.macs.values()) say(`${pad(r.vni, 8)}${pad(r.mac, 20)}${pad('remote', 8)}${pad(r.vtep, 18)}${r.ip || ''}`);
        return;
      }
      for (const m of e.maps()) say(`VNI ${m.vni}  VLAN ${m.vlan}  remote VTEPs: ${[...(e.vteps.get(Number(m.vni)) || [])].join(', ') || 'none'}  MACs: ${[...e.macs.values()].filter(x => Number(x.vni) === Number(m.vni)).length} remote`);
      return;
    }
    say(`Unknown command: ${p[0]}. Type help for an overview.`);
  } finally {
    sim.emit('cli', { devId: dev.id, cmd });
  }
}

export { PORTS };

// ---------------------------------------------------------------- IPv6 commands
function inet6Line(a) {
  const flags = a.state === 'duplicate' ? ' dadfailed tentative' : a.state === 'tentative' ? ' tentative' : '';
  return `    inet6 ${a.ip}/${a.len} scope ${a.scope}${a.origin === 'slaac' ? ' dynamic mngtmpaddr' : ''}${flags}`;
}
function route6Text(r, dev) {
  const dst = r.len === 0 ? 'default' : `${r.net}/${r.len}`;
  if (r.proto === 'C' || r.proto === 'K') return `${dst} dev ${r.dev} proto kernel metric 256`;
  if (r.proto === 'RA') return `${dst} via ${r.via} dev ${r.dev} proto ra metric 1024 expires ${Math.max(0, Math.round((r.until - dev.sim.time) / 1000))}sec`;
  if (!r.dev) return `${dst} via ${r.via}  (inactive: next hop not on any connected link${isLinkLocal6(r.via) ? ', a link-local next hop needs "dev"' : ''})`;
  return `${dst} via ${r.via} dev ${r.dev} metric 1024`;
}
function showIpv6Route(dev, say) {
  if (!dev.l3.v6.on) return say('IPv6 is turned off on this device');
  say('Codes: K - kernel route, C - connected, S - static, R - router advertisement');
  for (const r of dev.l3.v6.routes()) {
    const code = { C: 'C>*', K: 'K>*', S: r.dev ? 'S>*' : 'S  ', RA: 'R>*' }[r.proto];
    const dst = `${r.net}/${r.len}`;
    say(r.via ? `${code} ${dst} [${r.proto === 'S' ? (r.distance || 1) + '/0' : '0/1024'}] via ${r.via}, ${r.dev || 'inactive'}` : `${code} ${dst} is directly connected, ${r.dev}`);
