    fl.logSeq = this.record(dev, 'send', `sends via ${ifname}: ${summary(f)}`, { frame: f, tag: frame.type === 'stp' ? 'bpdu-sent' : hello ? 'hello-sent' : null,
      data: { to: toDev?.name || peer.dev, toId: peer.dev, toIf: peer.if, fromIf: ifname } }).seq;
    this.schedule(delay, () => {
