    cfg.ospf = { enabled: false, timers: 'fast', rid: '', ...(cfg.ospf || {}) };
    cfg.bfd = { enabled: false, interval: 300, mult: 3, ospf: false, ...(cfg.bfd || {}) };
    cfg.maxPaths ??= 4;
    cfg.ecmpHash ??= 'l3';
    cfg.ipv6 = { enabled: false, ra: [], rdnss: '', ...(cfg.ipv6 || {}) };
    cfg.ospf.ifaces ??= {};
  }
  if (t === 'router' || t === 'vtep') cfg.bgp = { enabled: false, asn: '', rid: '', timers: 'fast', networks: [], redistributeConnected: false, neighbors: [], ...(cfg.bgp || {}) };
  if (t === 'router' || t === 'server') cfg.dhcpServer = { enabled: false, pools: [], ...(cfg.dhcpServer || {}) };
  if (t === 'switch') {
    cfg.ports ??= {};
    for (const p of PORTS.switch) cfg.ports[p] = { mode: 'access', vlan: 1, allowed: '1-4094', native: 1, edge: false, cost: 4, ...(cfg.ports[p] || {}) };
    cfg.ageing ??= 300;
