    for (const [n, v] of Object.entries(this.cfg.ifaces || {})) {
      if (v?.dhcp) this.sim.schedule(600 + this.sim.random() * 600, () => { if (!this.l3.lease && !this.dhcpRunning(n)) this.dhclient(n, { boot: true }); });
    }
