        // Same conversation, or the same packet after NAT or a relay changed its addresses
        if ((f && t.keys.has(f.key)) || (e.trace && t.traces.has(e.trace))) {
          if (f) t.keys.add(f.key);
          if (e.trace) t.traces.add(e.trace);
