  }
  trackHighlight() {
    if (!this.track) return null;
    const devs = new Set(), edges = new Set();
    for (const m of this.flowMessages()) {
      if (this.flowSel && m.id !== this.flowSel) continue;
      for (const [, , a, b] of m.edges) { devs.add(a); if (b) { devs.add(b); edges.add(a + '|' + b); } }
