        h('span', { class: 'small' }, 'Multiplier'), numInput(b.mult, 2, 50, v => upd(() => b.mult = v ?? 3, `${dev.name}: BFD multiplier ${v}`))),
      h('label', { class: 'row small', style: { marginTop: '6px' } }, ospf, 'Watch the OSPF neighbors'),
