    h('div', { class: 'cfg-grid', style: { gridTemplateColumns: '120px 1fr', marginTop: '6px' } },
      h('span', {}, 'Local AS'), numInput(b.asn, 1, 4294967295, v => upd(() => b.asn = v ?? '', `${dev.name}: AS ${v}`), '65001'),
