    make: () => bgpPairTopo() },
  { id: 'ibgp', title: 'iBGP and eBGP with a provider', topics: ['BGP', 'iBGP', 'OSPF', 'Next hop'],
    text: 'An AS with three routers: OSPF carries the loopbacks, iBGP the external routes, eBGP talks to the provider. pc3 reaches the web server on the internet.',
    make: () => ibgpTopo() },
  { id: 'bgpmulti', title: 'Two providers (multihoming)', topics: ['BGP', 'Local preference', 'AS path prepending'],
    text: 'AS 65001 is connected to two providers. Which way do the packets of pc2 take to the web server, and which way do the answers come back? Change it with local preference and AS path prepending.',
    make: () => bgpMultiTopo() },
  { id: 'evpn', title: 'EVPN with three VTEPs', topics: ['EVPN', 'BGP', 'VXLAN', 'Route reflector'],
    text: 'The VTEPs find each other with BGP type 3 routes and learn every MAC with type 2 routes. No static flood lists, no flood and learn, ARP suppression on.',
    make: () => evpnTopo() },
  { id: 'failover', title: 'Failover with gratuitous ARP', topics: ['ARP', 'GARP', 'Failover'],
    text: 'The service address 10.0.0.100 moves from srvA to srvB. Try it with and without gratuitous ARP.',
    make: () => failoverTopo() },
  { id: 'tcppath', title: 'TCP across a bottleneck', topics: ['TCP', 'MSS', 'PMTUD'],
    text: 'Only MTU 1400 between r1 and r2. The web server has to shrink its segments.',
    make: () => tcpPathTopo() },
  { id: 'dhcp', title: 'DHCP with a relay', topics: ['DHCP', 'Relay', 'Broadcast'],
    text: 'Two clients get their address from a server in another network. r1 relays their broadcasts.',
    make: () => dhcpTopo({ relay: true }) },
  { id: 'nat', title: 'Home network with NAT', topics: ['NAT', 'PAT', 'Port forwarding'],
    text: 'Two PCs share one public address. Watch the router rewrite addresses and ports with conntrack -L.',
    make: () => natTopo({ nat: true, forward: true }) },
  { id: 'ospf', title: 'OSPF between three sites', topics: ['OSPF', 'SPF', 'Failover'],
    text: 'Three routers learn each other\'s networks by themselves. Disconnect a link and watch them reroute.',
    make: () => ospfTopo() },
  { id: 'vrrp', title: 'Redundant gateway with VRRP', topics: ['VRRP', 'Failover', 'Virtual MAC'],
    text: 'ra and rb share the gateway 10.0.0.1. Pull the master\'s cable while pc1 pings.',
    make: () => vrrpTopo() },
  { id: 'empty', title: 'Empty network', topics: ['Your own network'],
    text: 'An empty canvas for your own topology.',
    make: () => topo('My network', [], []) }
];

export function chainTopo() {
  return topo('Three routers in a row', [
    host('pc1', 80, 220, '10.0.1.10', 24, '10.0.1.1'),
    router('r1', 250, 220, { eth1: '10.0.1.1/24', eth2: '10.0.12.1/24' }, [['0.0.0.0/0', '10.0.12.2']]),
    router('r2', 420, 220, { eth1: '10.0.12.2/24', eth2: '10.0.23.2/24' }, [['10.0.1.0/24', '10.0.12.1'], ['10.0.4.0/24', '10.0.23.3']]),
    router('r3', 590, 220, { eth1: '10.0.23.3/24', eth2: '10.0.4.1/24' }, [['0.0.0.0/0', '10.0.23.2']]),
    server('srv1', 760, 220, '10.0.4.10', 24, '10.0.4.1')],
  [link('pc1', 'eth1', 'r1', 'eth1'), link('r1', 'eth2', 'r2', 'eth1'), link('r2', 'eth2', 'r3', 'eth1'), link('r3', 'eth2', 'srv1', 'eth1')]);
}
export function vlanTopo(trunked = true) {
  // A fresh object per switch, so changing one trunk never changes the other
  const up = () => trunked ? trunk('10,20', 1) : acc(1);
  return topo('VLANs over a trunk', [
    host('a10', 90, 110, '10.10.0.1'), host('a20', 90, 330, '10.20.0.1'),
    host('b10', 690, 110, '10.10.0.2'), host('b20', 690, 330, '10.20.0.2'),
    sw('s1', 270, 220, { eth1: acc(10), eth2: acc(20), eth8: up() }), sw('s2', 510, 220, { eth1: acc(10), eth2: acc(20), eth8: up() })],
  [link('a10', 'eth1', 's1', 'eth1'), link('a20', 'eth1', 's1', 'eth2'), link('b10', 'eth1', 's2', 'eth1'), link('b20', 'eth1', 's2', 'eth2'), link('s1', 'eth8', 's2', 'eth8')],
  [{ x: 20, y: 40, w: 760, h: 140, label: 'VLAN 10', kind: 'vlan' }, { x: 20, y: 262, w: 760, h: 140, label: 'VLAN 20', kind: 'vlan' }]);
}
export function vxlanTopo({ two = false, vni2 = 10010, port2 = 4789, mtu = 1500, flood2 = true } = {}) {
  const maps1 = [{ vni: 10010, vlan: 10, flood: ['10.255.0.2'], dstport: 4789, learning: true }];
  const maps2 = [{ vni: vni2, vlan: 10, flood: flood2 ? ['10.255.0.1'] : [], dstport: port2, learning: true }];
  if (two) { maps1.push({ vni: 10020, vlan: 20, flood: ['10.255.0.2'], dstport: 4789, learning: true }); maps2.push({ vni: 10020, vlan: 20, flood: ['10.255.0.1'], dstport: 4789, learning: true }); }
  const devs = [
    server('srv1', 90, 120, '192.168.10.11'), server('srv2', 790, 120, '192.168.10.12'),
    vtep('vtep1', 230, 260, { uplink: '10.0.1.2/24', lo: '10.255.0.1', routes: [['10.255.0.2/32', '10.0.1.1']], ports: { eth2: acc(10), eth3: acc(20) }, vxlans: maps1 }),
    vtep('vtep2', 650, 260, { uplink: '10.0.2.2/24', lo: '10.255.0.2', routes: [['10.255.0.1/32', '10.0.2.1']], ports: { eth2: acc(10), eth3: acc(20) }, vxlans: maps2 }),
    router('core', 440, 380, { eth1: '10.0.1.1/24', eth2: '10.0.2.1/24' }, [['10.255.0.1/32', '10.0.1.2'], ['10.255.0.2/32', '10.0.2.2']])];
  const links = [link('vtep1', 'eth1', 'core', 'eth1', mtu), link('vtep2', 'eth1', 'core', 'eth2', mtu), link('srv1', 'eth1', 'vtep1', 'eth2'), link('srv2', 'eth1', 'vtep2', 'eth2')];
  if (two) {
    devs.push(host('pc1', 90, 400, '192.168.20.11'), host('pc2', 790, 400, '192.168.20.12'));
    links.push(link('pc1', 'eth1', 'vtep1', 'eth3'), link('pc2', 'eth1', 'vtep2', 'eth3'));
  }
  return topo('VXLAN over a routed underlay', devs, links,
    [{ x: 20, y: 40, w: 860, h: 130, label: two ? 'Overlay: VNI 10010 (192.168.10.0/24) and VNI 10020 (192.168.20.0/24)' : 'Overlay: VNI 10010, 192.168.10.0/24', kind: 'overlay' },
      { x: 150, y: 320, w: 580, h: 120, label: 'Underlay: routed, only knows the VTEP loopbacks', kind: 'underlay' }]);
}

// -------------------------------------------------------------- Spanning tree, subinterfaces, services
const stpCfg = (enabled, prio = 32768, timers = 'fast', mode = 'stp') => ({ stp: { enabled, mode, priority: prio, timers } });
/** modes: one protocol for all switches, or one per switch: { sw1: 'rstp', sw3: 'stp' } */
const modeOf = (mode, id) => (typeof mode === 'string' ? mode : mode[id] || 'stp');
export function stpTriangle({ enabled = true, rootPrio = 32768, timers = 'fast', edge = false, mode = 'stp' } = {}) {
  const pcPort = edge ? { mode: 'access', vlan: 1, edge: true } : acc(1);
  const rapid = modeOf(mode, 'sw1') === 'rstp' || modeOf(mode, 'sw2') === 'rstp';
  return topo(!enabled ? 'Loop without spanning tree' : rapid ? 'Redundancy with rapid spanning tree' : 'Redundancy with spanning tree', [
    sw('sw1', 400, 110, {}, stpCfg(enabled, rootPrio, timers, modeOf(mode, 'sw1'))), sw('sw2', 230, 300, { eth5: pcPort }, stpCfg(enabled, 32768, timers, modeOf(mode, 'sw2'))), sw('sw3', 570, 300, { eth5: pcPort }, stpCfg(enabled, 32768, timers, modeOf(mode, 'sw3'))),
    host('pc1', 80, 300, '10.0.0.1'), host('pc2', 720, 300, '10.0.0.2')],
  [link('sw1', 'eth1', 'sw2', 'eth1'), link('sw1', 'eth2', 'sw3', 'eth1'), link('sw2', 'eth2', 'sw3', 'eth2'),
    link('pc1', 'eth1', 'sw2', 'eth5'), link('pc2', 'eth1', 'sw3', 'eth5')],
  [{ x: 160, y: 40, w: 480, h: 330, label: 'Redundant cabling: three paths, one loop', color: 'yellow' }]);
}
export function stpSquare({ mode = 'stp', timers = 'fast', edge = false } = {}) {
  const pc = edge ? { mode: 'access', vlan: 1, edge: true } : acc(1);
  return topo('Four switches in a ring', [
    sw('sw1', 240, 110, { eth5: pc }, stpCfg(true, 4096, timers, modeOf(mode, 'sw1'))), sw('sw2', 560, 110, {}, stpCfg(true, 32768, timers, modeOf(mode, 'sw2'))),
    sw('sw3', 560, 340, { eth5: pc }, stpCfg(true, 32768, timers, modeOf(mode, 'sw3'))), sw('sw4', 240, 340, {}, stpCfg(true, 32768, timers, modeOf(mode, 'sw4'))),
    host('pc1', 80, 110, '10.0.0.1'), host('pc3', 720, 340, '10.0.0.3')],
  [link('sw1', 'eth1', 'sw2', 'eth1'), link('sw2', 'eth2', 'sw3', 'eth1'), link('sw3', 'eth2', 'sw4', 'eth2'), link('sw4', 'eth1', 'sw1', 'eth2'),
    link('pc1', 'eth1', 'sw1', 'eth5'), link('pc3', 'eth1', 'sw3', 'eth5')],
  [{ x: 170, y: 40, w: 460, h: 370, label: 'Ring of four switches, sw1 is root', color: 'yellow' }]);
}
export function stickTopo(configured = true) {
  const r = { id: 'r1', type: 'router', name: 'r1', x: 400, y: 84, ifaces: { eth1: { ip: '', prefix: 24 } }, routes: [] };
  if (configured) {
    r.ifaces['eth1.10'] = { parent: 'eth1', vlan: 10, ip: '10.10.0.1', prefix: 24 };
    r.ifaces['eth1.20'] = { parent: 'eth1', vlan: 20, ip: '10.20.0.1', prefix: 24 };
  }
  return topo('Router-on-a-Stick', [r,
    sw('sw1', 400, 260, { eth1: acc(10), eth2: acc(10), eth3: acc(20), eth4: acc(20), eth8: trunk('10,20', 1) }),
    host('a1', 120, 200, '10.10.0.11', 24, '10.10.0.1'), host('a2', 120, 380, '10.10.0.12', 24, '10.10.0.1'),
    host('b1', 680, 200, '10.20.0.11', 24, '10.20.0.1'), server('b2', 680, 380, '10.20.0.12', 24, '10.20.0.1')],
  [link('a1', 'eth1', 'sw1', 'eth1'), link('a2', 'eth1', 'sw1', 'eth2'), link('b1', 'eth1', 'sw1', 'eth3'), link('b2', 'eth1', 'sw1', 'eth4'), link('r1', 'eth1', 'sw1', 'eth8')],
  [{ x: 30, y: 140, w: 210, h: 300, label: 'VLAN 10', color: 'blue' }, { x: 560, y: 140, w: 210, h: 300, label: 'VLAN 20', color: 'violet' },
    { x: 290, y: 14, w: 220, h: 146, label: 'Router with subinterfaces', color: 'gray' }]);
}
export function servicesTopo({ acl = [] } = {}) {
  const web = server('web', 640, 110, '10.20.0.80', 24, '10.20.0.1');
  web.services = [{ proto: 'tcp', port: 80, name: 'http', size: 3000 }, { proto: 'tcp', port: 443, name: 'https', size: 3000 }];
  const dns = server('dns', 640, 330, '10.20.0.53', 24, '10.20.0.1');
  dns.services = [{ proto: 'udp', port: 53, name: 'dns' }];
  dns.dns = [{ name: 'web.lab', ip: '10.20.0.80' }, { name: 'dns.lab', ip: '10.20.0.53' }, { name: 'intranet.lab', ip: '10.20.0.80' }];
  const c1 = host('client', 100, 220, '10.10.0.10', 24, '10.10.0.1');
  c1.resolver = '10.20.0.53';
  return topo('Web and DNS', [c1, router('r1', 300, 220, { eth1: '10.10.0.1/24', eth2: '10.20.0.1/24' }, [], { acl }), sw('sw1', 470, 220), web, dns],
    [link('client', 'eth1', 'r1', 'eth1'), link('r1', 'eth2', 'sw1', 'eth1'), link('web', 'eth1', 'sw1', 'eth2'), link('dns', 'eth1', 'sw1', 'eth3')],
    [{ x: 400, y: 40, w: 340, h: 380, label: 'Server network 10.20.0.0/24', color: 'green' }]);
}
/** DNS from the root down: a resolver in the own network, root, TLD and two authoritative servers on the internet */
export function dnsTopo() {
  const auth = (name, x, y, ip, gw, zone, dns) => {
    const d = server(name, x, y, ip, 24, gw);
    d.services = [{ proto: 'udp', port: 53, name: 'dns' }];
    d.dnsZone = zone; d.dns = dns;
    return d;
  };
  const client = host('client', 80, 130, '10.1.0.10', 24, '10.1.0.1');
  client.resolver = '10.1.0.53';
  const resolver = server('resolver', 80, 330, '10.1.0.53', 24, '10.1.0.1');
  resolver.services = [{ proto: 'udp', port: 53, name: 'dns' }];
  resolver.recursion = { enabled: true, roots: '198.41.0.4' };
  const web = server('web', 930, 330, '203.0.113.80', 24, '203.0.113.1');
  web.services = [{ proto: 'tcp', port: 80, name: 'http', size: 3000 }];
  return topo('DNS from the root down', [client, resolver, sw('sw1', 220, 230),
    router('r1', 370, 230, { eth1: '10.1.0.1/24', eth2: '10.0.12.1/24' }, [['0.0.0.0/0', '10.0.12.2']]),
    router('isp', 560, 230, { eth1: '10.0.12.2/24', eth2: '198.41.0.1/24', eth3: '192.0.2.1/24', eth4: '203.0.113.1/24' }, [['10.1.0.0/24', '10.0.12.1']]),
    auth('root', 560, 60, '198.41.0.4', '198.41.0.1', '.', [
      { name: '.', type: 'NS', value: 'a.root-servers.lab', ttl: 518400 }, { name: 'a.root-servers.lab', type: 'A', ip: '198.41.0.4', ttl: 518400 },
      { name: 'lab', type: 'NS', value: 'ns1.nic.lab', ttl: 172800 }, { name: 'ns1.nic.lab', type: 'A', ip: '192.0.2.53', ttl: 172800 }]),
    auth('nic', 780, 90, '192.0.2.53', '192.0.2.1', 'lab', [
      { name: 'lab', type: 'NS', value: 'ns1.nic.lab', ttl: 172800 }, { name: 'ns1.nic.lab', type: 'A', ip: '192.0.2.53', ttl: 172800 },
      { name: 'firma.lab', type: 'NS', value: 'ns1.firma.lab', ttl: 86400 }, { name: 'ns1.firma.lab', type: 'A', ip: '203.0.113.53', ttl: 86400 },
      { name: 'partner.lab', type: 'NS', value: 'ns.partner.lab', ttl: 86400 }, { name: 'ns.partner.lab', type: 'A', ip: '203.0.113.153', ttl: 86400 }]),
    sw('sw2', 760, 330),
    auth('ns1', 930, 200, '203.0.113.53', '203.0.113.1', 'firma.lab', [
      { name: 'firma.lab', type: 'NS', value: 'ns1.firma.lab', ttl: 86400 }, { name: 'ns1.firma.lab', type: 'A', ip: '203.0.113.53', ttl: 86400 },
      { name: 'www.firma.lab', type: 'A', ip: '203.0.113.80', ttl: 60 }, { name: 'shop.firma.lab', type: 'CNAME', value: 'www.firma.lab', ttl: 3600 },
      { name: 'mail.firma.lab', type: 'A', ip: '203.0.113.25', ttl: 3600 }]),
    web,
    auth('partner', 930, 460, '203.0.113.153', '203.0.113.1', 'partner.lab', [
      { name: 'partner.lab', type: 'NS', value: 'ns.partner.lab', ttl: 86400 }, { name: 'ns.partner.lab', type: 'A', ip: '203.0.113.153', ttl: 86400 },
      { name: 'portal.partner.lab', type: 'A', ip: '203.0.113.80', ttl: 300 }])],
  [link('client', 'eth1', 'sw1', 'eth1'), link('resolver', 'eth1', 'sw1', 'eth2'), link('sw1', 'eth8', 'r1', 'eth1'), link('r1', 'eth2', 'isp', 'eth1'),
    link('isp', 'eth2', 'root', 'eth1'), link('isp', 'eth3', 'nic', 'eth1'), link('isp', 'eth4', 'sw2', 'eth8'),
    link('ns1', 'eth1', 'sw2', 'eth1'), link('web', 'eth1', 'sw2', 'eth2'), link('partner', 'eth1', 'sw2', 'eth3')],
  [{ x: 20, y: 50, w: 420, h: 380, label: 'Own network with a resolver', color: 'blue' },
    { x: 470, y: 10, w: 160, h: 120, label: 'Root', color: 'gray' }, { x: 690, y: 30, w: 180, h: 120, label: 'TLD lab.', color: 'gray' },
    { x: 690, y: 160, w: 330, h: 370, label: 'Hosting provider', color: 'green' }]);
}
/** Dual stack: SLAAC and RDNSS from r1, static IPv6 routes between the routers, a server with A and AAAA */
export function ipv6Topo({ ra = true, rdnss = true, routes6 = true, v4 = true } = {}) {
  const v6 = (d, extra = {}) => { d.ipv6 = { enabled: true, ...extra }; return d; };
  const r1 = v6(router('r1', 420, 230, { eth1: '10.1.0.1/24', eth2: '10.0.12.1/24' }, v4 ? [['10.2.0.0/24', '10.0.12.2']] : []), { ra: ra ? ['eth1'] : [], rdnss: rdnss ? '2001:db8:2::53' : '' });
  r1.ifaces.eth1.ip6 = ['2001:db8:1::1/64']; r1.ifaces.eth2.ip6 = ['2001:db8:12::1/64'];
  if (routes6) r1.routes.push({ dst: '2001:db8:2::/64', via: '2001:db8:12::2' });
  const r2 = v6(router('r2', 620, 230, { eth1: '10.0.12.2/24', eth2: '10.2.0.1/24' }, v4 ? [['10.1.0.0/24', '10.0.12.1']] : []));
  r2.ifaces.eth1.ip6 = ['2001:db8:12::2/64']; r2.ifaces.eth2.ip6 = ['2001:db8:2::1/64'];
  if (routes6) r2.routes.push({ dst: '2001:db8:1::/64', via: '2001:db8:12::1' });
  const pc = (name, y, ip) => { const d = v6(host(name, 170, y, v4 ? ip : '', 24, v4 ? '10.1.0.1' : ''), { slaac: true }); return d; };
  const web = v6(server('web', 880, 140, '10.2.0.80', 24, '10.2.0.1'), { slaac: false, gw: '2001:db8:2::1' });
  web.ifaces.eth1.ip6 = ['2001:db8:2::80/64'];
  web.services = [{ proto: 'tcp', port: 80, name: 'http', size: 3000 }];
  const dns = v6(server('dns', 880, 330, '10.2.0.53', 24, '10.2.0.1'), { slaac: false, gw: '2001:db8:2::1' });
  dns.ifaces.eth1.ip6 = ['2001:db8:2::53/64'];
  dns.services = [{ proto: 'udp', port: 53, name: 'dns' }];
  dns.dns = [{ name: 'www.lab', type: 'A', ip: '10.2.0.80', ttl: 300 }, { name: 'www.lab', type: 'AAAA', ip: '2001:db8:2::80', ttl: 300 },
    { name: 'legacy.lab', type: 'A', ip: '10.2.0.80', ttl: 300 }];
  return topo('Dual stack: IPv4 and IPv6', [pc('pc1', 120, '10.1.0.10'), pc('pc2', 340, '10.1.0.11'), sw('sw1', 290, 230), r1, r2, sw('sw2', 750, 230), web, dns],
    [link('pc1', 'eth1', 'sw1', 'eth1'), link('pc2', 'eth1', 'sw1', 'eth2'), link('sw1', 'eth8', 'r1', 'eth1'), link('r1', 'eth2', 'r2', 'eth1'),
      link('r2', 'eth2', 'sw2', 'eth8'), link('web', 'eth1', 'sw2', 'eth1'), link('dns', 'eth1', 'sw2', 'eth2')],
    [{ x: 30, y: 50, w: 460, h: 380, label: 'LAN 2001:db8:1::/64, SLAAC', color: 'blue' }, { x: 690, y: 50, w: 300, h: 380, label: 'Servers 2001:db8:2::/64', color: 'green' }]);
}
/** Two sites joined by a WireGuard tunnel across a provider that only routes public addresses */
export const WG_KEYS = { gwA: wgGenKey('gwA'), gwB: wgGenKey('gwB'), laptop: wgGenKey('laptop') };
export function vpnTopo({ peerB = true, allowedB = '10.99.0.1/32, 10.1.0.0/24', allowedA = '10.99.0.2/32, 10.2.0.0/24' } = {}) {
  const wg = (d, addr, peers) => {
    d.ifaces.wg0 = { ip: addr, prefix: 24 };
    d.wg = { enabled: true, listenPort: 51820, privateKey: WG_KEYS[d.id], mtu: 1420, peers };
    return d;
  };
  const gwA = wg(router('gwA', 330, 230, { eth1: '10.1.0.1/24', eth2: '198.51.100.1/24' }, [['0.0.0.0/0', '198.51.100.254']]), '10.99.0.1',
    [{ name: 'gwB', publicKey: wgPubKey(WG_KEYS.gwB), endpoint: '203.0.113.1:51820', allowedIps: allowedA, keepalive: 25 }]);
  const gwB = wg(router('gwB', 730, 230, { eth1: '203.0.113.1/24', eth2: '10.2.0.1/24' }, [['0.0.0.0/0', '203.0.113.254']]), '10.99.0.2',
    peerB ? [{ name: 'gwA', publicKey: wgPubKey(WG_KEYS.gwA), endpoint: '', allowedIps: allowedB, keepalive: 0 }] : []);
  const srv = server('srvB', 900, 230, '10.2.0.10', 24, '10.2.0.1');
  srv.services = [{ proto: 'tcp', port: 80, name: 'http', size: 3000 }];
  return topo('Site-to-site VPN with WireGuard', [host('pcA', 80, 140, '10.1.0.10', 24, '10.1.0.1'), host('pcA2', 80, 330, '10.1.0.200', 24, '10.1.0.1'), sw('swA', 200, 230), gwA,
    router('isp', 530, 230, { eth1: '198.51.100.254/24', eth2: '203.0.113.254/24' }), gwB, srv],
  [link('pcA', 'eth1', 'swA', 'eth1'), link('pcA2', 'eth1', 'swA', 'eth2'), link('swA', 'eth8', 'gwA', 'eth1'), link('gwA', 'eth2', 'isp', 'eth1'), link('isp', 'eth2', 'gwB', 'eth1'), link('gwB', 'eth2', 'srvB', 'eth1')],
  [{ x: 20, y: 60, w: 380, h: 340, label: 'Site A 10.1.0.0/24', color: 'blue' }, { x: 450, y: 120, w: 160, h: 200, label: 'Internet', color: 'gray' },
    { x: 660, y: 60, w: 320, h: 340, label: 'Site B 10.2.0.0/24', color: 'green' }]);
}
// -------------------------------------------------------------- BGP
const bgpCfg = (asn, neighbors, networks = [], extra = {}) => ({ enabled: true, asn, rid: '', timers: 'fast', networks, redistributeConnected: false, neighbors, ...extra });
const nb = (ip, remoteAs, extra = {}) => ({ ip, remoteAs, updateSource: '', nextHopSelf: false, rrClient: false, localPref: '', med: '', multihop: 0, ...extra });
/** Two companies, two autonomous systems, one eBGP session */
export function bgpPairTopo({ r2 = true, r2As = 65001 } = {}) {
  const r1 = router('r1', 330, 230, { eth1: '10.1.0.1/24', eth2: '10.0.12.1/30' }, [], { bgp: bgpCfg(65001, [nb('10.0.12.2', 65002)], ['10.1.0.0/24']) });
  const r2d = router('r2', 590, 230, { eth1: '10.0.12.2/30', eth2: '10.2.0.1/24' }, [], { bgp: r2 ? bgpCfg(65002, [nb('10.0.12.1', r2As)], ['10.2.0.0/24']) : bgpCfg(65002, [], [], { enabled: false }) });
  return topo('eBGP between two autonomous systems', [host('pc1', 100, 230, '10.1.0.10', 24, '10.1.0.1'), r1, r2d, server('srv2', 820, 230, '10.2.0.10', 24, '10.2.0.1')],
    [link('pc1', 'eth1', 'r1', 'eth1'), link('r1', 'eth2', 'r2', 'eth1'), link('r2', 'eth2', 'srv2', 'eth1')],
    [{ x: 30, y: 110, w: 380, h: 240, label: 'AS 65001', color: 'blue' }, { x: 510, y: 110, w: 380, h: 240, label: 'AS 65002', color: 'green' }]);
}
/** An AS with three routers: OSPF inside, iBGP between the loopbacks, eBGP to the provider */
export function ibgpTopo({ nhs = true, fullMesh = true, rr = false, lo1 = true } = {}) {
  const ospf = (ifs) => ospfOn(Object.fromEntries(ifs.map(([k, v]) => [k, v || {}])));
  const ib = (ip, extra = {}) => nb(ip, 65001, { updateSource: lo1 ? 'lo' : '', ...extra });
  const isp = router('isp', 120, 120, { eth1: '192.0.2.1/30', eth2: '198.51.100.1/24' }, [], { bgp: bgpCfg(65100, [nb('192.0.2.2', 65001)], ['198.51.100.0/24']) });
  const r1 = router('r1', 330, 230, { eth1: '192.0.2.2/30', eth2: '10.0.12.1/30', lo: '10.255.0.1/32' }, [], {
    bgp: bgpCfg(65001, [nb('192.0.2.1', 65100), ib('10.255.0.2', { nextHopSelf: nhs }), ...(fullMesh ? [ib('10.255.0.3', { nextHopSelf: nhs })] : [])]) });
  r1.ospf = ospf([['eth2'], ['lo', { passive: true }]]);
  const r2 = router('r2', 540, 230, { eth1: '10.0.12.2/30', eth2: '10.0.23.2/30', lo: '10.255.0.2/32' }, [], {
    bgp: bgpCfg(65001, [ib('10.255.0.1', { rrClient: rr }), ib('10.255.0.3', { rrClient: rr })]) });
  r2.ospf = ospf([['eth1'], ['eth2'], ['lo', { passive: true }]]);
  const r3 = router('r3', 750, 230, { eth1: '10.0.23.3/30', eth2: '10.3.0.1/24', lo: '10.255.0.3/32' }, [], {
    bgp: bgpCfg(65001, [...(fullMesh ? [ib('10.255.0.1')] : []), ib('10.255.0.2')], ['10.3.0.0/24']) });
  r3.ospf = ospf([['eth1'], ['eth2', { passive: true }], ['lo', { passive: true }]]);
  const web = server('web', 120, 360, '198.51.100.80', 24, '198.51.100.1');
  web.services = [{ proto: 'tcp', port: 80, name: 'http', size: 3000 }];
  return topo('iBGP inside an AS, eBGP to the provider', [isp, web, r1, r2, r3, host('pc3', 900, 360, '10.3.0.10', 24, '10.3.0.1')],
    [link('isp', 'eth1', 'r1', 'eth1'), link('isp', 'eth2', 'web', 'eth1'), link('r1', 'eth2', 'r2', 'eth1'), link('r2', 'eth2', 'r3', 'eth1'), link('r3', 'eth2', 'pc3', 'eth1')],
    [{ x: 30, y: 40, w: 200, h: 400, label: 'Provider AS 65100', color: 'gray' }, { x: 260, y: 120, w: 720, h: 330, label: 'AS 65001: OSPF inside, iBGP between the loopbacks', color: 'blue' }]);
}
/** One AS with two providers: which exit is used, and which entrance do the others use? */
export function bgpMultiTopo({ lpR3 = '', lpR1 = '', lpR3Ibgp = '', prependR1 = 0 } = {}) {
  const ospf = (ifs) => ospfOn(Object.fromEntries(ifs.map(([k, v]) => [k, v || {}])));
  const ib = (ip, extra = {}) => nb(ip, 65001, { updateSource: 'lo', ...extra });
  const isp1 = router('isp1', 330, 70, { eth1: '192.0.2.1/30', eth2: '198.51.100.1/24', eth3: '203.0.113.1/30' }, [], { bgp: bgpCfg(65100, [nb('192.0.2.2', 65001), nb('203.0.113.2', 65200)], ['198.51.100.0/24']) });
  const isp2 = router('isp2', 750, 70, { eth1: '192.0.2.5/30', eth3: '203.0.113.2/30' }, [], { bgp: bgpCfg(65200, [nb('192.0.2.6', 65001), nb('203.0.113.1', 65100)]) });
  const web = server('web', 120, 70, '198.51.100.80', 24, '198.51.100.1');
  web.services = [{ proto: 'tcp', port: 80, name: 'http', size: 3000 }];
  const r1 = router('r1', 330, 260, { eth1: '192.0.2.2/30', eth2: '10.0.12.1/30', lo: '10.255.0.1/32' }, [], {
    bgp: bgpCfg(65001, [nb('192.0.2.1', 65100, { localPref: lpR1, prepend: prependR1 }), ib('10.255.0.2', { nextHopSelf: true }), ib('10.255.0.3', { nextHopSelf: true })]) });
  r1.ospf = ospf([['eth2'], ['lo', { passive: true }]]);
  const r2 = router('r2', 540, 380, { eth1: '10.0.12.2/30', eth2: '10.0.23.2/30', eth3: '10.2.0.1/24', lo: '10.255.0.2/32' }, [], {
    bgp: bgpCfg(65001, [ib('10.255.0.1'), ib('10.255.0.3')], ['10.2.0.0/24']) });
  r2.ospf = ospf([['eth1'], ['eth2'], ['eth3', { passive: true }], ['lo', { passive: true }]]);
  const r3 = router('r3', 750, 260, { eth1: '192.0.2.6/30', eth2: '10.0.23.3/30', lo: '10.255.0.3/32' }, [], {
    bgp: bgpCfg(65001, [nb('192.0.2.5', 65200, { localPref: lpR3 }), ib('10.255.0.1', { nextHopSelf: true }), ib('10.255.0.2', { nextHopSelf: true, localPref: lpR3Ibgp })]) });
  r3.ospf = ospf([['eth2'], ['lo', { passive: true }]]);
  return topo('Two providers: choosing the way out and in', [web, isp1, isp2, r1, r2, r3, host('pc2', 540, 520, '10.2.0.10', 24, '10.2.0.1')],
    [link('web', 'eth1', 'isp1', 'eth2'), link('isp1', 'eth1', 'r1', 'eth1'), link('isp1', 'eth3', 'isp2', 'eth3'), link('isp2', 'eth1', 'r3', 'eth1'),
      link('r1', 'eth2', 'r2', 'eth1'), link('r2', 'eth2', 'r3', 'eth2'), link('r2', 'eth3', 'pc2', 'eth1')],
    [{ x: 30, y: 10, w: 400, h: 130, label: 'Provider 1, AS 65100 (with the web server)', color: 'gray' }, { x: 650, y: 10, w: 200, h: 130, label: 'Provider 2, AS 65200', color: 'gray' },
      { x: 250, y: 200, w: 600, h: 380, label: 'Our AS 65001', color: 'blue' }]);
}
/** EVPN: three VTEPs learn about each other and about all MACs over BGP, the spine reflects the routes */
export function evpnTopo({ rr = true, evpn = ['vtep1', 'vtep2', 'vtep3'], vni = {}, suppress = true, nbrEvpn = ['vtep1', 'vtep2', 'vtep3'] } = {}) {
  const v = (n, x) => {
    const id = 'vtep' + n;
    const d = vtep(id, x, 240, { uplink: `10.0.${n}.2/24`, lo: `10.255.0.${n}`, routes: [['10.255.0.0/24', `10.0.${n}.1`]], ports: { eth2: acc(10) },
      vxlans: [{ vni: vni[id] ?? 10010, vlan: 10, flood: [], dstport: 4789, learning: true, evpn: evpn.includes(id), arpSuppress: suppress }] });
    d.bgp = bgpCfg(65000, [nb('10.255.0.254', 65000, { updateSource: 'lo', evpn: true })]);
    return d;
  };
  const spine = router('spine', 450, 440, { eth1: '10.0.1.1/24', eth2: '10.0.2.1/24', eth3: '10.0.3.1/24', lo: '10.255.0.254/32' },
    [['10.255.0.1/32', '10.0.1.2'], ['10.255.0.2/32', '10.0.2.2'], ['10.255.0.3/32', '10.0.3.2']],
    { bgp: bgpCfg(65000, [1, 2, 3].map(n => nb(`10.255.0.${n}`, 65000, { updateSource: 'lo', rrClient: rr, evpn: nbrEvpn.includes('vtep' + n) }))) });
  return topo('EVPN: BGP as the control plane of VXLAN', [v(1, 170), v(2, 450), v(3, 730), spine,
    server('srv1', 170, 90, '192.168.10.11'), server('srv2', 450, 90, '192.168.10.12'), server('srv3', 730, 90, '192.168.10.13')],
  [link('vtep1', 'eth1', 'spine', 'eth1'), link('vtep2', 'eth1', 'spine', 'eth2'), link('vtep3', 'eth1', 'spine', 'eth3'),
    link('srv1', 'eth1', 'vtep1', 'eth2'), link('srv2', 'eth1', 'vtep2', 'eth2'), link('srv3', 'eth1', 'vtep3', 'eth2')],
  [{ x: 40, y: 30, w: 820, h: 120, label: 'Overlay: VNI 10010, 192.168.10.0/24', kind: 'overlay' },
    { x: 60, y: 360, w: 780, h: 160, label: 'Underlay: routed, the spine is the BGP route reflector', kind: 'underlay' }]);
}
export function failoverTopo() {
  const a = server('srvA', 600, 110, '10.0.0.100'), b = server('srvB', 600, 330, '10.0.0.12');
  return topo('Failover with gratuitous ARP', [host('client', 120, 220, '10.0.0.5'), sw('sw1', 360, 220), a, b],
    [link('client', 'eth1', 'sw1', 'eth1'), link('srvA', 'eth1', 'sw1', 'eth2'), link('srvB', 'eth1', 'sw1', 'eth3')],
    [{ x: 500, y: 40, w: 220, h: 380, label: 'Cluster, service address 10.0.0.100', color: 'orange' }]);
}
export function tcpPathTopo({ fwAcl = [] } = {}) {
  const web = server('web', 840, 220, '10.0.2.80', 24, '10.0.2.1');
  web.services = [{ proto: 'tcp', port: 80, name: 'http', size: 6000 }];
  return topo('TCP across a bottleneck', [host('client', 80, 220, '10.0.1.10', 24, '10.0.1.1'),
    router('r1', 270, 220, { eth1: '10.0.1.1/24', eth2: '10.0.12.1/24' }, [['0.0.0.0/0', '10.0.12.2']]),
    router('r2', 460, 220, { eth1: '10.0.12.2/24', eth2: '10.0.23.2/24' }, [['10.0.1.0/24', '10.0.12.1'], ['10.0.2.0/24', '10.0.23.3']]),
    router('fw', 650, 220, { eth1: '10.0.23.3/24', eth2: '10.0.2.1/24' }, [['0.0.0.0/0', '10.0.23.2']], { acl: fwAcl }), web],
  [link('client', 'eth1', 'r1', 'eth1'), link('r1', 'eth2', 'r2', 'eth1', 1400), link('r2', 'eth2', 'fw', 'eth1'), link('fw', 'eth2', 'web', 'eth1')],
  [{ x: 210, y: 130, w: 310, h: 150, label: 'Tunnel section, MTU 1400', color: 'orange' }]);
