    }
  }
  setState(n, s, why) {
    const prev = n.state;
    n.state = s;
    if (prev === 'Down' || s === 'Down') this.dev.bfd?.sync();
    const ok = s === 'Full';
    this.dev.record(ok ? 'ok' : 'info', `OSPF neighbor ${n.rid} (${n.ip} on ${n.ifname}): ${prev} → ${s}, ${why}`, { tag: 'ospf-neighbor', data: { rid: n.rid, state: s, ifname: n.ifname } });
