    for (const i of this.ifs()) {
      if (i.name !== 'lo' && !this.l3.linkUp(i.name)) continue;
      for (const n of this.nbrs.values()) if (n.ifname === i.name && n.state === 'Full') links.push({ type: 'router', rid: n.rid, cost: i.cost, ifname: i.name });
