    if (cur && cur.seq >= lsa.seq) return;
    this.lsdb.set(lsa.rid, clone(lsa));
    this.dev.record('learn', `OSPF: router LSA of ${lsa.rid} (sequence ${lsa.seq}, ${lsa.links.length} links) installed`, { frame, tag: 'ospf-lsa', data: { rid: lsa.rid } });
    this.flood(lsa, from);
