  }
  flood(lsa, from) {
    const ifs = new Set([...this.nbrs.values()].filter(n => n.state === 'Full' || n.state === 'Exchange').map(n => n.ifname));
    if (from) ifs.delete(from.ifname);
    for (const ifname of ifs) this.sendLsu(ifname, [lsa]);
