  sendLsu(ifname, lsas) {
    if (!lsas.length) return;
    const src = this.l3.ifIp(ifname);
    if (!src) return;
    const pkt = ipPacket({ src, dst: '224.0.0.5', ttl: 1, proto: PROTO.OSPF, l4: { kind: 'ospf', type: 'lsu', rid: this.rid, area: '0.0.0.0', lsas: clone(lsas) } });
